	0x48, 0x8B, 0xFA,              // mov rdi, rdx           the entry to remove
	0x48, 0x8B, 0xD9,              // mov rbx, rcx           the list
	0x48, 0x8D, 0x51, 0x10,        // lea rdx, [rcx+10h]     the list's lock
