// Evil Urn
//
// Four evil urn features in one plugin. Each one is switched on and off in
// its own section of celestialrayone.evil-urn.toml, and each one is checked
// against the game on its own: a feature whose checks fail is left out and
// reported in the log and by the console command, the others still install.
//
//   [spawn_chance]  per-room chance of a random urn, by difficulty
//   [boss_affixes]  extra random affixes for the boss an urn spawns
//   [blocklist]     monster types an urn must never spawn
//   [monster_roll]  a weighted roll of the urn's monster on every opening
//
// Built against D2R 3.3 in the D2RLoader 1.3.1 process image (base
// 0x140000000), PluginSDK 0.3.0. Everything below was read out of the live
// image and disassembled before being relied on.
//
// ===========================================================================
// The urn itself: objects.txt OperateFn 68 at 0x590960
// ===========================================================================
//   The OperateFn table is at 0x23A51C0, slots 0 to 74. Its NULL slots match
//   2.4 and D2MOO (0, 11, 13, 17, 35-38, 60, 62-64), slot 74 is new in 3.x,
//   and the slots Ruff's corpus names line up: 6 = 0x5DC570 TowerTome,
//   15 = 0x58F680 Portal, 32 = 0x528270 Bank. Slot 68 (0x23A53E0) holds
//   0x590960, which is D2MOO's OBJECTS_OperateFunction68_EvilUrn step for
//   step: neutral-mode gate, chest drop, operating mode, ENDANIM event, then
//
//     5909F4  48 8B 4F 18           mov  rcx, [rdi+18h]
//     5909F8  BA FF 00 00 00        mov  edx, 0FFh
//     5909FD  E8 FE 30 BC FF        call 153B00                 ; seed roll 0..254
//     590A02  3B 83 44 01 00 00     cmp  eax, [rbx+144h]        ; objects.txt Parm4
//     590A08  0F 87 C6 00 00 00     ja   590AD4                 ; no spawn
//     ...                                                       ; eax = urn level id
//     590A24  48 8B 0F              mov  rcx, [rdi]             ; game
//     590A27  8B D0                 mov  edx, eax
//     590A29  48 8B 89 D0 01 00 00  mov  rcx, [rcx+1D0h]
//     590A30  E8 0B 7D F7 FF        call 508740                 ; monster region of the level
//     590A35  0F B6 48 10           movzx ecx, byte [rax+10h]   ; monster type count
//     590A39  48 8D 70 14           lea  rsi, [rax+14h]
//     590A3D  48 6B D1 34           imul rdx, rcx, 34h
//     590A41  48 8D 58 14           lea  rbx, [rax+14h]         ; rbx = first entry
//     590A45  48 03 F2              add  rsi, rdx               ; rsi = end
//     590A48  48 3B DE              cmp  rbx, rsi
//     590A4B  0F 84 7E 00 00 00     je   590ACF                 ; no types
//   loop:
//     590A51  48 8B 07              mov  rax, [rdi]
//     590A54  0F BF 13              movsx edx, word [rbx]       ; the entry's monstats id
//     590A57  0F B6 88 06 01 00 00  movzx ecx, byte [rax+106h]  ; data context
//     590A5E  E8 4D 6B B0 FF        call 975B0                  ; its MonStats2 record
//     590A63  48 85 C0              test rax, rax
//     590A66  75 11                 jne  590A79
//     590A68  ...                   assert, then 590A88
//     590A79  0F B6 80 F0 00 00 00  movzx eax, byte [rax+0F0h]  ; mode flags
//     590A80  23 05 52 8C 80 01     and  eax, [1D996D8]         ; gdwBitMasks[2] = 4, walk
//     590A86  75 0B                 jne  590A93                 ; spawn
//     590A88  48 83 C3 34           add  rbx, 34h               ; next type
//     590A8C  48 3B DE              cmp  rbx, rsi
//     590A8F  75 C0                 jne  590A51
//     590A91  EB 3C                 jmp  590ACF                 ; list exhausted, no spawn
//     590A93  48 8B 4F 08           mov  rcx, [rdi+8]
//     590A97  0F BF 1B              movsx ebx, word [rbx]
//     ...
//     590ACA  E8 B1 8D F0 FF        call 499880                 ; the boss pack
//
//   The spawn chance column at record +144h is the one D2R 3.3's objects.txt
//   names Parm4 (its loader maps Parm0..Parm4 to +134h..+144h; 2.4 and D2MOO
//   called the slot Parm7). The urn row has 255 there, so an opened urn
//   always tries to spawn. The urn spawns the FIRST type in the level's list
//   that has a walk mode. 0x975B0 is the MonStats2-from-monstats-id getter:
//   monstats stride 1FCh, MonStats2 index word at +4Ch, MonStats2 stride
//   128h, null for an id out of range.
//
// ===========================================================================
// [spawn_chance]: per-room urn chance by difficulty
// ===========================================================================
//   0x510F00  the per-room object filler. For each of the level's 8 ObjGrp
//             slots it rolls the room seed % 100 and fires the group when the
//             roll is <= ObjPrb, so ObjPrb N means (N + 1)% per room. A second
//             roll % 100 walks the group's members, adding up PROB, and the
//             first member the roll falls under is placed through
//             PopulateFn table[objects.txt PopulateFn](game, room, DENSITY,
//             object id, 100).
//   0x239BC10 the PopulateFn table, 10 slots, slot 0 NULL:
//               1 0x50D340   2 0x50CF10   3 0x50D1D0   4 0x50C370
//               5 0x50C8C0   6 0x50E070   7 0x50DB60   8 0x50C180
//               9 0x50E1F0
//             The only other caller is 0x510880 (a single group, same call).
//   0x50E1F0  PopulateFn 9, used by the urn (objects.txt row 466):
//             (game, room, density, objectId, chance). It turns the room size
//             into a try count, (density * ((w * h) >> 7)) >> 8 in subtiles,
//             and places at most ONE object, stopping at the first try that
//             finds a free spot. Its only references are its table slot and
//             its unwind entry.
//   0x2EFBF0  room seed accessor: test rcx,rcx / je / lea rax,[rcx+0A0h] / ret.
//             The game's roll is seed = lo * 0x6AC690C5 + hi (64-bit), stored
//             back as (lo, hi), value = low 32 bits.
//   0x48FF40  game context builder: movzx eax, byte [rdx+104h] at +19h is
//             the difficulty byte (0 Normal, 1 Nightmare, 2 Hell).
//
//   Slot 9 of the PopulateFn table is replaced with PopulateHook. For an
//   object id on the list it rolls room seed % txt_percent and keeps the
//   placement only when the roll is below the current difficulty's percent,
//   so a room gets the urn with exactly the difficulty percent. A difficulty
//   whose percent equals txt_percent does not roll at all. Every other
//   object, and every kept placement, goes to the original unchanged.
//
// ===========================================================================
// [boss_affixes]: extra random affixes for the urn's boss
// ===========================================================================
//   0x499880  the boss-pack spawner the urn calls at 590ACA. After creating
//             the boss it calls, at 0x499ACD,
//               0x49E160 (game, boss, championChance, minimum, maximum, list)
//             with minimum = maximum = difficulty + 1 (movzx r9d, difficulty /
//             inc r9d / the same value stored as the fifth argument), then
//             spawns the minions (0x49EAD0), which copy the boss's xfer
//             affixes.
//   0x49E160  the affix roll. With championChance set it first rolls
//             seed % 100 against monumod.txt constants row 0 (20 in ESR,
//             "Champion chance to spawn instead of Unique"); on a hit the
//             pack becomes a champion pack (rank flag 4) with one champion
//             affix and the function returns. Otherwise it rolls
//             minimum + seed % (maximum - minimum + 1) affixes, capped so the
//             monster holds at most 9, drawing without repeats and stopping
//             early when nothing is left to draw. Its callers are 0x499880
//             and 0x49AC30 (only reached from 0x591600, not from the urn).
//
//   Slot 68 of the OperateFn table is replaced with UrnOperateHook, which
//   counts the urn calls in progress on this thread and calls the urn
//   unchanged. 0x49E160 gets an inline hook: while an urn call is in
//   progress, minimum and maximum are both raised by extra_affixes. Inside
//   the urn call the only path to 0x49E160 is the boss-pack spawn, so exactly
//   the urn's boss is affected. The champion roll, the cap and the draw are
//   the game's own.
//
// ===========================================================================
// [blocklist]: monster types an urn must never spawn
// ===========================================================================
//   Port of the ESR D2R 2.4 memory patches (hook 3BF80C redirecting the urn's
//   call to sub_1400A4440 into the wrapper cave 36AE90, with a zero-terminated
//   id table at 36AEC4) to D2R 3.3. In 2.4 the walk test was a call,
//   sub_1400A4440(id, 2), so the cave could wrap it and return 0 for a
//   blocked id. In 3.3 that call no longer exists: the compiler inlined it
//   into the three instructions at 590A79. There is nothing to wrap, so this
//   feature takes over the test itself.
//
//   The 15 bytes at 590A79 (movzx / and / jne) become a jmp into a stub in a
//   private region next to the image, the rest NOPed. The stub replays the
//   test. When the type has a walk mode it also looks the entry's id up in a
//   bitmap built from the config. A blocked id leaves through 590A88, the
//   exit a type without a walk mode takes, and everything else leaves
//   through 590A93, the untouched spawn. The urn's own loop therefore does
//   the skipping, and a level whose types are all blocked or unable to walk
//   takes the vanilla list-exhausted path and spawns nothing.
//
//   Why the window is safe:
//     - it starts and ends on instruction boundaries, the only branch into it
//       is the jne at 590A66 onto its first byte, and nothing references a
//       byte inside it;
//     - rbx (the entry) and rsi (the end) are nonvolatile and never touched;
//     - rax, rcx, rdx and r8 are dead on both exits: 590A88 either loops to
//       590A51, which reloads rax, edx and ecx before its call, or runs out
//       to 590ACF, which reloads rcx and calls; 590A93 reloads rcx and
//       calls, then sets rdx, r8 and r9 before the spawn call;
//     - the flags are dead on both exits, and the stub never uses the stack.
//
//   The stub was assembled with keystone and decoded back with capstone, and
//   every relative jump lands on an instruction start. It was then emulated
//   with unicorn against the original 15 bytes: 5,640 cases over mode-flag
//   bytes, ids 0 to 65535 and several blocklists, and 11,520 more over all 256
//   mode-flag bytes with the region built from the constants in this file.
//   Retargeted (the state it is put in on unload) it matches the original
//   exactly. Armed, it spawns exactly when the type can walk and is not
//   blocked, with rbx, rsi, rdi, rbp, rsp and r9-r15 preserved and both
//   counters exact.
//
// ===========================================================================
// [monster_roll]: a weighted roll of the urn's monster on every opening
// ===========================================================================
//   Vanilla has no roll. The loop above spawns the FIRST type in the level's
//   monster region list that has a walk mode, and that list is built once
//   per level when the game is created (D2MOO MONSTERREGION_InitializeAll:
//   levels.txt NumMon types drawn from Mon1-Mon25 on Normal or NMon1-NMon25
//   on Nightmare and Hell, keeping monstats.txt isSpawn monsters). Every urn
//   in a level therefore spawns the same type for the whole game.
//
//   The urn fetches the list with one call:
//
//     590A24  48 8B 0F              mov  rcx, [rdi]             ; game
//     590A27  8B D0                 mov  edx, eax               ; level id
//     590A29  48 8B 89 D0 01 00 00  mov  rcx, [rcx+1D0h]        ; region table
//     590A30  E8 0B 7D F7 FF        call 508740                 ; table[level id]
//
//   0x508740 is movsxd rax, edx / mov rax, [rcx+rax*8] / ret (Ruff's corpus:
//   MonsterRegionGetter). After it returns, the urn reads only the type
//   count byte at +10h and the entries from +14h (stride 34h, the monstats
//   id in each entry's first word), nothing else of the region.
//
//   The call at 590A30 is pointed at a thunk in a private page next to the
//   image:
//
//     +00  4C 8B C7                 mov  r8, rdi                ; operate args
//     +03  FF 25 07 00 00 00        jmp  qword ptr [rip+7]
//     +10  dq                       RegionHook, or 508740 once retargeted
//
//   rdi holds the urn's operate arguments for the whole function (set at
//   590966 and never written again: game at +0, the seed holder at +18h).
//   r8 is volatile, and the urn writes it before any later read. The thunk
//   jumps rather than calls, so RegionHook returns straight to 590A35 on
//   exactly the stack the game built for 508740.
//
//   RegionHook calls 508740 itself, then rolls over the real list:
//     - a type takes part when the game's own walk test passes for it:
//       0x975B0 (the MonStats2 getter the loop calls at 590A5E), mode byte
//       +F0h AND gdwBitMasks[2] (0x1D996D8, which holds 4);
//     - with [blocklist] enabled, blocked ids never take part;
//     - each type left weighs default_weight or its monster_weights entry;
//     - one SEED_RollLimitedRandomNumber (0x153B00) on the seed holder the
//       urn rolled Parm4 with (operate +18h, game +21D0h) picks among them.
//   It hands the urn a copy of the region header whose count is 1, followed
//   by the picked entry, or 0 when nothing is left. The urn's own loop, walk
//   test, [blocklist] stub and boss pack spawn then run unchanged on that
//   list of one. The copy is thread_local, and the urn is done reading it at
//   590A97, before anything on that thread can reach the hook again.
//
//   Retargeted (the state it is put in on unload) the thunk is mov r8, rdi /
//   jmp 508740, which is the original call: 508740 never reads r8.
//
// ===========================================================================
// How the four fit together
// ===========================================================================
//   [boss_affixes] owns OperateFn slot 68 and the entry of 0x49E160;
//   [blocklist] owns the 15 bytes at 590A79 inside the urn; [spawn_chance]
//   owns PopulateFn slot 9; [monster_roll] owns the call at 590A30. None of
//   them touches what another one owns. The checks never read bytes another
//   feature changes, with one exception: [monster_roll] needs the walk test
//   at 590A79 and accepts it either untouched or holding the [blocklist]
//   jump, which runs the same test.

// 590960: push rdi / sub rsp,50h / mov rdi,rcx / mov rcx,[rcx+8] /
// call 34AB60 (unit mode) / test / je / return 0 / xor edx,edx /
// mov rcx,rdi / call 5930B0 (chest drop) / test rax,rax / je 590AF4.

// 590991: the rest of the urn's setup up to its spawn chance roll (operating
// mode, objects.txt record, ENDANIM event). Nothing in it writes rdi, which
// holds the operate arguments from 590966 to the end of the function.

// 590A24: the monster region of the urn's level: mov rcx,[rdi] /
// mov edx,eax / mov rcx,[rcx+1D0h] / call 508740. [monster_roll] owns the
// call at +0Ch.

// 50E1F0: push rbp/rsi/rdi/r12-r15 / sub rsp,60h / security cookie /
// movzx edi, r8b (density) / mov r14d, r9d (object id) / mov rbp, rdx (room) /
// mov rsi, rcx (game) / test rcx, rcx / jne.

// 499AAD: movzx r9d, byte [rbp-51h] (difficulty) / lea rax,[rbp-11h] /
// mov r8d,[rbp+5Fh] / inc r9d / mov [rsp+28h],rax / mov rdx,r12 /
// mov rcx,r15 / mov [rsp+20h],r9d / call 49E160.

// 49E160: push rbx/rbp/rsi/rdi/r12/r14/r15 / sub rsp,160h. Eighteen bytes,
// whole instructions, nothing relative; the next instruction is the
// security cookie load.

// 153B00: SEED_RollLimitedRandomNumber(seed, bound), the whole function. For
// bound > 0 it steps the seed (lo * 6AC690C5h + hi, stored back as lo, hi)
// and returns the low 32 bits mod bound; 0 or less returns 0 and leaves the
// seed alone.

// 975B0: the MonStats2 record of a monstats id (data context in cl, id in
// edx), up to its monstats bounds check. It returns null for an id out of
// range.

// The thunk the call at 590A30 is pointed at, alone in its own page:
//   +00  4C 8B C7                 mov  r8, rdi             ; operate arguments
//   +03  FF 25 07 00 00 00        jmp  qword ptr [rip+7]   ; the qword at +10h
//   +09  CC x 7                   padding, so the target is 8-aligned
//   +10  dq                       RegionHook, or 508740 once retargeted

// ---------------------------------------------------------------------------
// Hook region
// ---------------------------------------------------------------------------
//   One allocation within rel32 reach of the image, never freed:
//     +0000  code page      PAGE_EXECUTE_READ   the stub below
//     +1000  counters page  PAGE_READWRITE      written by the stub
//     +2000  bitmap, 8 KB   PAGE_READONLY       bit n set = monstats id n blocked
//   The stub reads and writes nothing but the game and this region, so it
//   never depends on this DLL being loaded.

// +00  0F B6 80 F0 00 00 00     movzx eax, byte ptr [rax+0F0h]   ; 590A79
// +07  48 B9 dq                 mov   rcx, gdwBitMasks[2]
// +11  23 01                    and   eax, dword ptr [rcx]        ; 590A80
// +13  75 15                    jne   +2Ah                        ; 590A86
// +15  FF 25 00 00 00 00        jmp   qword ptr [rip+0]           ; next type
// +1B  dq                       590A88
// +23  CC x 7                   padding, so the dispatch qword is 8-aligned
// +2A  FF 25 00 00 00 00        jmp   qword ptr [rip+0]           ; dispatch
// +30  dq                       +38h armed, +6Ah retargeted
// +38  0F B7 0B                 movzx ecx, word ptr [rbx]         ; the entry's id
// +3B  48 BA dq                 mov   rdx, bitmap
// +45  89 C8                    mov   eax, ecx
// +47  C1 E8 03                 shr   eax, 3
// +4A  0F B6 04 02              movzx eax, byte ptr [rdx+rax]
// +4E  41 89 C8                 mov   r8d, ecx
// +51  41 83 E0 07              and   r8d, 7
// +55  44 0F A3 C0              bt    eax, r8d
// +59  72 1D                    jc    +78h                        ; blocked
// +5B  48 BA dq                 mov   rdx, counters
// +65  F0 48 FF 42 08           lock inc qword ptr [rdx+8]        ; spawned
// +6A  FF 25 00 00 00 00        jmp   qword ptr [rip+0]           ; spawn
// +70  dq                       590A93
// +78  48 BA dq                 mov   rdx, counters
// +82  F0 48 FF 02              lock inc qword ptr [rdx]          ; skipped
// +86  89 4A 10                 mov   dword ptr [rdx+10h], ecx    ; last skipped id
// +89  EB 8A                    jmp   +15h                        ; next type

// The part of a monster region the urn reads after 590A30: the type count at
// +10h and the entries from +14h. RegionHook hands the urn this copy, holding
// the picked entry alone.

// Points the thunk at the game's own getter, so the patched call behaves
// exactly like the original one. The qword is 8-aligned, so the store is a
// single atomic write even while a game thread runs the thunk.

// ---------------------------------------------------------------------------
// monster-drop-cap
//
// Raises the vanilla ceiling of 6 items per monster drop to a configurable
// number. Nothing else about dropping changes: treasure class selection, pick
// counts, NoDrop, quality rolls, Magic Find and the RNG are all untouched.
//
// Target: Diablo II: Resurrected 3.3.93847 (also 3.2.92777 and Steam
// 3.3.93787 -- those builds share an executable identity for patching).
//
// Safety model: the RVAs below are against image base 0x140000000, and nothing
// is installed unless the bytes already there match byte for byte. On a build
// this plugin does not recognise it installs nothing, logs loudly and stays
// loaded so the console command can explain why. An unrecognised build is a
// no-op, never a mis-patch.
//
// ---------------------------------------------------------------------------
// Where the cap lives, and how that was established
// ---------------------------------------------------------------------------
//
// The public server drop entry is TREASURECLASS_GenerateDrops at RVA 0x441300.
// It is a thin wrapper: it resolves the treasure class record from the id and
// tail-calls the real generator sub_1404404F0 (RVA 0x4404F0), forwarding all
// ten arguments unchanged. sub_1404404F0 has exactly two callers, 0x44148C
// inside that wrapper and 0x59333D, so hooking the generator covers strictly
// more ground than hooking the wrapper.
//
// Its tenth argument is the drop cap. The generator opens with:
//
//   0x4405F7  mov  eax, [rbp+948h]        ; a10, the requested cap
//   0x4405FD  mov  [rsp+68h], eax         ; the working cap
//   0x440601  test r14, r14               ; a8, the caller's output array
//   0x440604  jnz  00440614
//   0x440606  test eax, eax
//   0x440608  jg   0044062C               ; a10 > 0 -> use it as given
//   0x44060A  mov  dword ptr [rsp+68h], 6 ; <- THE VANILLA CAP
//   0x440612  jmp  0044062C
//   0x440614  test eax, eax               ; a8 set but a10 zero -> assert
//
// and enforces it at 0x44115F with `if (++*count >= cap) goto done;` after each
// item is spawned.
//
// Two branches, and the difference between them is the whole safety argument
// for this plugin:
//
//   a8 == 0  -- no output array. The caller wants items on the floor and does
//              not collect pointers to them. a10 <= 0 means "use the default",
//              and the default is the hard-coded 6. This is the monster path,
//              and it is the ONLY branch this plugin touches.
//
//   a8 != 0  -- the caller passed an array of a10 QWORDs, filled at 0x44114F
//              with `array[count] = item`. Here a10 is a BUFFER CAPACITY, not
//              a policy knob. Raising it would write past the caller's array.
//              The hook never modifies a10 when a8 is non-null.
//
// The monster call site (0x447E17, reached through the wrapper) sets both to
// zero: `xor ecx,ecx` then `mov [rsp+38h],rcx` for a8 and `mov [rsp+48h],ecx`
// for a10. That is exactly the branch above, so a monster drop is capped at 6
// today.
//
// The unit that is dropping is argument 2. Unit type is the dword at Unit+0x00
// (0 player, 1 monster, 4 item), so the hook can scope itself to monsters
// without calling into the game.
// ---------------------------------------------------------------------------

constexpr std::uint8_t GenerateDropsEntry[] {
	0x4C, 0x8B, 0xDC,                         // mov  r11, rsp
	0x55,                                     // push rbp
	0x53,                                     // push rbx
	0x49, 0x8D, 0xAB, 0x08, 0xF7, 0xFF, 0xFF, // lea  rbp, [r11-8F8h]
	0x48, 0x81, 0xEC, 0xE8, 0x09, 0x00, 0x00, // sub  rsp, 9E8h
};

// The displaced bytes: mov r11,rsp / push rbp / push rbx. Three complete
// instructions, all position independent, no rip-relative operand and no
// branch. `mov r11, rsp` captures the frame base before the pushes, which the
// `lea rbp, [r11-8F8h]` two instructions later consumes -- relocating it into
// the trampoline is correct because the trampoline is entered with RSP exactly
// as the real entry would see it.

constexpr std::uint8_t DefaultCapBlock[] {
	0x8B, 0x85, 0x48, 0x09, 0x00, 0x00,       // mov  eax, [rbp+948h]      ; a10
	0x89, 0x44, 0x24, 0x68,                   // mov  [rsp+68h], eax
	0x4D, 0x85, 0xF6,                         // test r14, r14             ; a8
	0x75, 0x0E,                               // jnz  00440614
	0x85, 0xC0,                               // test eax, eax
	0x7F, 0x22,                               // jg   0044062C
	0xC7, 0x44, 0x24, 0x68, 0x06, 0x00, 0x00, 0x00, // mov [rsp+68h], 6
	0xEB, 0x18,                               // jmp  0044062C
};

// An installed inline hook cannot be withdrawn, and the trampoline lives in
// this module, so there is deliberately nothing to undo here. The loader is
// expected to keep the DLL resident for the life of the process.

// ---------------------------------------------------------------------------
// cast-rate-cap
//
// Raises (or lowers) the point at which faster cast rate stops paying.
//
// Vanilla stops the cast animation rate at 175 percent, which the engine's own
// diminishing-return curve reaches at exactly 200 faster cast rate. Every point
// past 200 is dead. This plugin makes that ceiling follow a faster cast rate
// number you choose, so the curve keeps paying up to the cap you set.
//
// Target: Diablo II: Resurrected 3.3.93847 (also 3.2.92777, Steam 3.3.93787 --
// those builds share an executable identity for patching purposes).
//
// Safety model: the address below is an RVA against image base 0x140000000, and
// nothing is written unless the bytes already at that RVA match byte for byte.
// On any build the plugin does not recognise it installs nothing, logs loudly
// and stays loaded so the console command can explain why. An unrecognised
// build is therefore a no-op, never a mis-patch.
//
// Configuration: <scope>\d2rloader\config\celestialrayone.cast-rate-cap.toml,
// created with documented defaults on first run. The default is 200, the
// vanilla cap, so installing this plugin and changing nothing changes nothing.
// The config is read once at load, so edits need a game restart.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// The site
// ---------------------------------------------------------------------------
//
//   sub_140350B40 is the merged animation-rate updater: one function that
//   computes the animation rate for attacking, casting, blocking, hit recovery
//   and movement, dispatching on unit type and animation mode. Casting is the
//   branch taken for a player in mode 10, a monster in mode 7, and a player
//   running a sequence skill whose own animation mode is cast:
//
//     00350C14  BA 02 00 00 00      mov  edx, 2         ; rate kind 2 = cast
//     00350C19  48 8B CE            mov  rcx, rsi       ; the unit
//     00350C1C  E8 <rel32>          call 003516C0       ; diminished stat
//     00350C21  BB FF 7F 00 00      mov  ebx, 7FFFh
//     00350C26  8D 48 64            lea  ecx, [rax+64h] ; + 100
//     00350C29  B8 AF 00 00 00      mov  eax, 0AFh      ; <- the ceiling, 175
//     00350C2E  3B C8               cmp  ecx, eax
//     00350C30  0F 4F C8            cmovg ecx, eax      ; clamp
//     00350C33  ...                 rate * AnimationSpeed / 100
//
//   003516C0 is the shared diminishing-return helper. It reads a five row
//   table at 141D00B60, twelve bytes per row, {diminish flag, constant, stat
//   id}: attack {1,120,93}, hit recovery {1,120,99}, cast {1,120,105}, block
//   {1,120,102}, movement {1,150,96}. For a diminished row it returns
//   value * K / (K + value). So the cast branch is:
//
//     effective = 120 * FCR / (FCR + 120)
//     rate      = min(100 + effective, 175)
//     animSpeed = AnimationSpeed * rate / 100
//     frames    = ceil(256 * FramesPerDirection / animSpeed) - 1
//
//   effective reaches 75 at exactly 200 FCR, which is 175, which is the
//   ceiling. That is the whole of the vanilla FCR cap: it is not a separate
//   rule, it is this one immediate.
//
//   The fix rewrites that immediate to the rate the curve produces at the
//   configured cap, so the cap lands exactly where you asked:
//
//     ceiling(cap) = 100 + 120 * cap / (cap + 120)
//
//   which gives 175 at 200 (vanilla, unchanged) and 196 at 500. Five bytes, one
//   instruction, one operand. The instruction, its length and every surrounding
//   branch are untouched, so there is nothing to relocate and no hook.
//
//   Scope: this is the cast branch only. Attack, block, hit recovery and
//   movement have their own ceilings elsewhere in the same function and are not
//   touched. Monsters cast through this branch too, so a monster carrying FCR
//   is subject to the same cap.
//
//   The 95 byte window 00350C14..00350C72 is verified before writing, which
//   also proves the rate kind, the helper it calls, the + 100 base and the
//   clamp pair that consumes the immediate. The five byte pattern occurs
//   exactly once inside it.

// ===========================================================================
// Forever States (celestialrayone.forever-states)
// ===========================================================================
//
// Server side. A state that a skill grants (skills.txt aurastate) lasts while
// the player has one of the stats its rules name, comes back after save and
// exit, and Consume is no longer ended by binding demons. When the player
// loses the stat (the item giving it is unequipped or swapped out), a state
// the plugin was keeping ends on the next frame through the game's own expiry.
// A rule can carry a marker stat: it then covers only a state whose own stats
// hold the marker, so each book keeps only the Consume of its own demon.
//
// ---------------------------------------------------------------------------
// 1. How a skill state ends (D2R 3.3.93847, D2RLoader 1.3.1 process image)
// ---------------------------------------------------------------------------
//   States like Consume are made by 433D20, the generic state applicator (a
//   loader thunk into D2RCore!ApplyWideTimedStatEffect, args below). It stores
//   the end frame on the state's stat list as a float at +24h, sets timer flag
//   2 at +1Ch, and schedules unit event 12 for that frame (EVENT_SetEvent
//   48B720). When event 12 fires, 42EA80 runs the expiry pass, which tail-calls
//   j_ExpireWideUnitStats 2F82F0 with the game frame [game+170h]; it removes
//   every list that has flag 2 and an end frame at or before that frame. The
//   client's copy of a state is made with no timer, so only the server ends it.
//
// ---------------------------------------------------------------------------
// 2. Why binding demons ended Consume
// ---------------------------------------------------------------------------
//   Consume is srvdofunc 159 (521970). skills.txt periodic = 1, so the timer
//   437230 runs it again every perdelay frames with unit flag 20000000h at
//   +128h set. In that mode it reads stat 84 from the Consume list (the pettype
//   of the eaten pet, written at cast), asks 4FEB50 whether that pettype is
//   full, and if so unlinks (2F7920) and frees (2F4180) the list. Binding up to
//   the petmax that Consume itself raised filled the pettype, so Consume ended,
//   petmax dropped back and the pet list trimmed the extra demons. Bind Demon's
//   own srvdofunc 158 (520CF0) only works on the demon, never on the caster.
//
// ---------------------------------------------------------------------------
// 3. What the plugin does
// ---------------------------------------------------------------------------
//   Keep (every frame). A player's stat regen event (type 3) reschedules itself
//   every frame at 42E634 through EVENT_SetEvent. A relay on that call checks
//   each rule state on the player after the event is set. Which stats keep a
//   state depends on its own stat list. A rule with a marker covers only a
//   list holding that marker (read with the game's reader 2F5DF0, layer 0,
//   above 0), and a list holding any of its skill's markers is judged by
//   those rules alone. A list holding none is judged by the rules without a
//   marker. For Consume the markers are the stats monpet.txt consumestat gives
//   for the demon eaten (written by the cast at 521D57), so each book keeps
//   only its own demon's Consume.
//     - a stat that covers the state is present: the end frame is kept at
//       least HoldFrames ahead (2F7AB0), and the state is marked as kept;
//     - none present on a kept state: the end frame becomes the current frame
//       and an event 12 is set for the next frame, so the game's own expiry
//       pass removes it (state bit, client update and remove callback
//       included);
//     - none present on a list holding a marker, kept or not: it ends the same
//       way, so a marked state never lasts a frame without its stat, cast
//       without it included;
//     - any other state that was never kept keeps its normal timer.
//   A kept state remembers the markers its list held. Consume's cast removes
//   the old list before it makes the new one (4370B0 at 521B34 clears every
//   state of the aurastate's states.txt group, consume's own included), so a
//   list holding other markers is a new cast and is judged anew.
//   Consume. An inline hook on 521970 returns 1 in periodic mode while a stat
//   that covers the player's Consume list is present, which is the value that
//   branch returns when it removes nothing.
//   Save. The player save 52F090 writes the bound demon area last through
//   533AE0, once into a measuring buffer (call at 52F717) and once for real
//   (52F830). Relays on both calls append one "FRVS" block after whatever
//   533AE0 wrote, Summon Enhancements' blocks included. 52F090 takes the save
//   size from the cursor after those calls, so the block is counted.
//   Load. The player load 52E910 reads the bound demon area through 531510
//   (call at 52EFC8) and never reads its cursor again. A relay on that call
//   finds the block (scanning from the area's start, CRC-checked) and rebuilds
//   the kept states BEFORE 531510 runs, so Summon Enhancements brings the
//   demons back with Consume's doubled pet cap already there. Pet caps are
//   worked out again later (5005A0 works every pettype's petmax out and trims
//   the pets over it, run among others by the state remove callback 436240);
//   with Consume rebuilt first, that never finds the cap halved. Item stats do
//   not count at load, so the rule's stat is checked afterwards: the state is
//   kept on probation until a stat that covers it counts, or ends 15 s after
//   the player is in the world without one. A saved state no rule can keep any
//   more is not rebuilt.
//   Every helper the plugin calls is proven through a game call that reaches
//   it, never by its entry bytes, so plugins hooking those entries (crossbow-
//   charges, damage-overflow-fix) do not switch this one off.
//   Save rule. A state is written when the plugin keeps it or a stat that
//   covers it is present. If the game saves after a kept state is already
//   gone, the copy the keep check takes every HoldFrames is written instead.
//   Rebuild. Exactly what Consume's cast does: 433D20, then j_SetWideListStat
//   2F3030 for every saved stat, then 350B40 (the unit speed refresh Consume
//   calls), the last one once the player is in a room (34B440). A state the
//   game refuses at load is tried again at world entry (the relay on the
//   53BC60 call at 4856F1, the last call of 485350) and then every frame.
//
// ---------------------------------------------------------------------------
// 4. Layouts relied on (each read the same way by the game code named)
// ---------------------------------------------------------------------------
//   Unit: +0 type (0 player), +8 unit id, +128h extra flags (34FB00).
//   Game: +106h data context byte (521970), +170h current frame (42E615).
//   State stat list: +1Ch flags, +24h end frame (float, 2F7AB0), +28h skill,
//   +2Ch skill level (written by ApplyWideTimedStatEffect), +30h stat records,
//   +38h record count; a record is 16 bytes, key (stat << 32 | layer) then the
//   value (D2RCore!ReadWideListStat). Before saving, the first records are
//   read back through the game's own reader 2F5DF0 and must match.
//   skills.txt record: +A0h aurastate (521970).
//
// ===========================================================================

// ---------------------------------------------------------------------------
// Byte witnesses (read from the live IDB)
// ---------------------------------------------------------------------------
// Every function the plugin calls is proven by a game call that reaches it,
// never by its own entry bytes: other plugins hook some of those entries
// (damage-overflow-fix rewrites the 2F3030 thunk, crossbow-charges hooks the
// player regen handler), and their hooks must not switch this plugin off.

struct Witness {
    std::uint64_t       rva;
    const std::uint8_t* bytes;
    std::uint32_t       size;
    const char*         name;
};

// 521970, srvdofunc 159. In periodic mode, a player with a stat that covers
// the Consume list keeps the state: return what that branch returns when it
// removes nothing. Without a list that branch removes nothing either.

// 52EFC8: the kept states are rebuilt BEFORE 531510 reads the bound demon
// area, so Consume's doubled pet cap is there for the demons. The block sits
// after the demon blocks, so it is found by scanning from the area's start
// (its CRC keeps a demon block from being taken for it).

// Frenzy Speed
//
// A stat makes Frenzy faster: every point takes one frame off each of
// Frenzy's swings. Frenzy and nothing else.
//
// Everything below was read out of the D2RLoader 1.3.1 process image. Every
// site, offset and register used here is checked byte for byte at load, and
// nothing is installed when a check fails.
//
// ---------------------------------------------------------------------------
// 1. How Frenzy is timed
// ---------------------------------------------------------------------------
//   Eastern Sun's skills.txt Frenzy row (574) is anim SQ, seqnum 11,
//   UseAttackRate 1. A player using it sits in mode 18 (SQ) and plays
//   sequence 11, compiled into the exe (resolver 3CB890, table 2386650): the
//   same 17 rows for all 14 weapon classes, 6 bytes each
//   {word, mode, frame, dir, event}:
//     steps 0..8    mode 7 (A1)   frames 1..14, event 1 on step 4 (main hand swing)
//     steps 9..16   mode 15 (S3)  frames 2..11, event 1 on step 9 (off hand swing)
//   The mode start 34C880 calls the sequence installer 34D900 and then the
//   rate update 350B40 (34CB42, 34CB53). The installer leaves:
//     unit+40h  rows        3CB850 (slot +0)
//     unit+48h  length      3CB830 (slot +8) << 8, 17 << 8 for Frenzy
//     unit+4Ch  position    0
//     unit+54h  rate        256, until 350B40 sets it
//     unit+64h  countdown   3CB870 (slot +0Ch) << 8, also 17 << 8
//   Every server frame 3476B0 runs with a multiplier of 1.0 (4459BA loads
//   1.0f from 1CBA904) and, for a sequence (3476F1..347767):
//     position  = (position + rate) mod length
//     countdown = countdown - rate, end flag (unit+128h bit 27) at <= 0
//   So a sequence lasts ceil(length / rate) frames: ceil(4352 / rate) for
//   Frenzy, both swings together.
//
// ---------------------------------------------------------------------------
// 2. Hits
// ---------------------------------------------------------------------------
//   After every advance 351970 asks 3CB6C0 for the frame's event: with the
//   position unchanged it is the current step's own event, otherwise the LAST
//   non-zero event among the steps entered (old step + 1 .. new step). A frame
//   that wraps past the end enters no step at all. So two hits in one frame
//   count once, and a hit skipped by the final, wrapping frame is lost. For
//   Frenzy both hits need at least 3 frames: at 2 the second hit is lost, at
//   1 both are. The plugin plays each length it considers frame by frame
//   (EveryHitLands) and never goes below the shortest one at which every hit
//   of the sequence lands.
//
// ---------------------------------------------------------------------------
// 3. Where the speed is set
// ---------------------------------------------------------------------------
//   UNITS_UpdateAnimRateAndVelocity 350B40 keeps the unit in rsi throughout.
//   Mode 18 with skills.txt UseAttackRate takes the attack path (IAS, weapon
//   speed, dual wield averaging, the -30 sequence penalty, the 15..175 clamp)
//   and the cast and attack paths both end at:
//     350C69  movsx eax, bx
//     350C6C  mov [rsi+54h], eax       ; the rate a sequence advances by
//     350C6F  mov [rsi+68h], bx        ; the same rate as a word
//     350C73  call 362360              ; every path reaches this call
//   The call at 350C73 goes to a relay that hands the unit to the hook and
//   then continues to 362360 (a getter without arguments) exactly as before.
//   The hook acts only when the dword at unit+54h equals the word at
//   unit+68h, meaning the rate came through that store. Paths that write the
//   word alone (block, get hit, movement, fixed speeds) are never touched.
//   Other plugins: crossbow-charges redirects 351597 and checks 351102..351151,
//   351482..35149D and 351597..3515A3; faster-cast-rate-cap patches 350C29 and
//   checks 350C14..350C72; whirlwind-follow-cursor checks 350B40..350B6C and
//   350FDC..3510B8. 350C73..350C77 is in none of them.
//
// ---------------------------------------------------------------------------
// 4. The rule
// ---------------------------------------------------------------------------
//   For a player in mode 18 with a sequence installed whose used skill
//   ([[unit+100h]+18h], record, first word: 34BA40 -> 33E090 -> 33E080) is
//   frenzy_skill_id:
//     game frames = ceil(length / game rate)
//     swings      = steps carrying an event (2 for Frenzy)
//     wanted      = game frames - stat * swings, at least 1
//     frames      = the shortest length from wanted up at which every hit
//                   lands, and only if that is faster than the game
//     rate        = the slowest rate that finishes within frames
//   A negative stat adds frames the same way, taking the fastest rate that
//   needs at least that many. The stat goes through the game's own reader
//   (2F5020, D2RCore's wide stat read), so ids above 511 work. 350B40 is shared
//   code, so the server (timing, hits) and every client (animation) apply the
//   same rule to the same numbers.

// 350C59..350C8B: the end of the cast and attack paths (rsi = unit). xor r14d,r14d /
// clamp 0..7FFFh / movsx eax,bx / mov [rsi+54h],eax / mov [rsi+68h],bx / call 362360
// (the redirected call, offset 1Ah) / mov [rbp+18h],rsi / call 980E0.

// 34D927..34D989 in the installer 34D900 (rbx = unit): rows = 3CB850 -> [rbx+40h];
// [rbx+48h] = 3CB830 (steps << 8); [rbx+54h] = 100h; qword [rbx+4Ch] = 0;
// [rbx+64h] = 3CB870 << 8; first step through 351970 (position 0 to 0).

// 3476F1..347767 in the per-frame advance 3476B0 (rbx = unit, xmm6 = multiplier):
// advance = trunc([rbx+54h] * xmm6); position [rbx+4Ch] += advance, mod [rbx+48h];
// [rbx+64h] -= advance; 351970(unit, old position); end flag [rbx+128h] bit 1Bh
// set once [rbx+64h] <= 0.

// 3CB6C0..3CB7B4: rows of 6 bytes; mode +2, frame +3, dir +4 of the new step; event:
// the new step's own +5 when new == old, else the last non-zero +5 of steps
// old/256 + 1 .. new/256 (none when the position wrapped).

struct Witness {
    std::uint64_t       rva;
    const std::uint8_t* bytes;
    std::uint32_t       size;
    const char*         name;
};

// Entered by the call at 350C73, so [rsp] returns to 350C78. Seven pushes plus
// the return address keep rsp 16-byte aligned for the inner call. The site
// held a call, so the game expects every volatile register to be clobbered;
// they are kept anyway, and the stub leaves by jumping to the original target
// with the stack exactly as it came in, so 362360 returns straight to 350C78.

// Herald Bosses
//
// Monsters that become heralds count as bosses and prime evils, as if their
// monstats.txt row had boss = 1 and primeevil = 1. What that changes in game
// is written up in celestialrayone.herald-bosses.toml.
//
// Read out of the D2RLoader 1.3.1 process image and D2RCore.dll 1.3.1
// (SHA-256 2a868d01...89b948fdeb5a2). Every site is checked byte for byte at
// load; a part whose check fails is not installed and the log names it.
//
// 1. HERALDS
//   MonsterData (unit+10h) +1Ah holds the rank flags. A herald carries 200h,
//   the flag the game's Aura Enchanted routine tests (0x495F69) and D2RCore's
//   herald code tests as byte +1Bh bit 1. It is tested when the game asks, so
//   a monster counts from the moment it becomes a herald.
//
// 2. WHERE THE GAME ASKS
//   monstats.txt boss and primeevil are bits 6 and 7 of the flags dword at
//   record +3Ch (parser 0x39DB30, bitfield columns). The game asks through
//   three helpers:
//     0x3AEFF0  MONSTERS_IsBoss (record, unit), 25 callers: stun 0x451C30,
//               freeze 0x451570, Crushing Blow, SUNITDMG_CalculateTotalDamage
//               0x44DF10, skills, AI, the affix rules in 0x498510..0x49AEB0
//     0x3AF080  the same, false for monstats rows 546 to 550
//     0x3B0250  MONSTERS_IsPrimeEvil (unit), 7 callers: 0x44DF10 (the
//               difficultylevels.txt PrimeEvil damage columns), aura filters
//               0x439C10, AI 0x595270, 0x5D0F10, 0x5D6870
//   Each ends with  movzx eax, byte [record+3Ch] / and eax, [mask]  where the
//   mask is gdwBitMasks[6] (0x1D996E8, 40h) or [7] (0x1D996EC, 80h). Those
//   ten bytes jump to a stub that does the same and, when the result is 0
//   and the unit is a herald, returns the mask. The entries stay untouched
//   (crushing-blow-modifier checks the first 16 bytes of 0x3AEFF0).
//   One game routine tests the boss bit itself:
//     0x34C7EF  AIUTIL_CanUnitSwitchAi, its "no bosses" gate (rbx = unit,
//               rdi = record), used by Conversion, Revive and the other AI
//               switches when they ask for it
//   D2RCore tests the prime evil bit itself once:
//     ApplyResistanceComponentWithPrimeEvilThreat +6Dh (D2RCore+0x82678D),
//     the prime evil threat bookkeeping after a player's hit (rax = record,
//     [r14+18h] = the monster that was hit)
//   Both get the same kind of stub: the original test first, then the
//   herald flag.
//
// 3. LEFT ALONE
//   The boss bit reads that set a monster's level at spawn (0x543B50, done
//   before any monster can be a herald) and the level a treasure class is
//   upgraded by (TREASURECLASS_GenerateDrops 0x441300, and 0x43DF20, same
//   noratio + boss test): herald drops keep scaling with the herald's level.
//   D2RCore's herald code (0x40CF60, 0x40D1D0, 0x40E7A0), which tests the
//   herald flag and the record's boss bit together to tell boss heralds from
//   replaced monsters. Every other read of these two masks in game code
//   tests another bit (killable, flying, placespawn, npc) or another table.

// ---------------------------------------------------------------------------
// Stubs. Position independent: the masks and the absolute return addresses
// are filled in at load.
//   StubBossRbx    record rbx, unit rdi (0x3AEFF0 and 0x3AF080)
//   StubPrimeRax   record rax, unit rdi (0x3B0250)
//   StubSwitchAi   record rdi, unit rbx (0x34C7EF)
//   StubCoreThreat record rax, monster [r14+18h] (D2RCore)
// Each keeps the original test, then: unit+10h MonsterData, byte +1Bh bit 1
// (rank flag 200h). Only rax/eax, rcx and the flags change, all of them
// dead at every place the stubs return to.
// ---------------------------------------------------------------------------

struct Witness {
	std::uint64_t       rva;
	const std::uint8_t* bytes;
	std::uint32_t       size;
};

struct ExeSite {
	const char*                  name;
	bool                         boss;          // herald_boss, else herald_prime_evil
	std::uint64_t                rva;           // the bytes that now jump to the stub
	const std::uint8_t*          original;
	std::uint32_t                size;
	const Witness*               checks;
	std::uint32_t                checkCount;
	const std::uint8_t*          stub;
	std::uint32_t                stubSize;
	std::uint64_t                maskRva;
	bool                         maskLowByte;   // test al, imm8
	std::array<std::size_t, 2>   maskAt;        // 0 = unused
	std::array<std::size_t, 2>   targetAt;      // 0 = unused
	std::array<std::uint64_t, 2> targetRva;
	bool                         installed;
	std::array<std::uint8_t, 16> patch;
};

// Hex Debuff Installer (auraeventfunc 36, WarApplyHexDebuff).
//
// See celestialrayone.hex-debuff-installer.toml for the full write-up. In short:
//
//   auraeventfunc 36 puts the skill's auratargetstate on the unit it hits. Only when
//   that state is 217 (hexpurgedebuff, hardcoded: `cmp dword [rsp+74h], 0D9h` at
//   51FFB6, `jne 520060` at 51FFC3) does it also register the skill's Param1 as an
//   event function on that unit for damagedbymissile, damagedinmelee and hextrigger.
//   The registrations carry no installer: sub_140438470 passes a literal 0 to the
//   single-event registrar sub_140438230 (`mov qword [rsp+48h], 0` at 438504), so
//   every node stores installer type 6, id -1.
//
//   auraeventfunc 33 (SkillActivateSubskill) tests aurastatcalc4 by whether the column
//   holds a formula (`cmp dword [rsi+94h], 0` at 42F3A9), not by its value. When it
//   does, the caster is looked up from the node's installer (sub_14048FE80). Type 6
//   finds nothing and the function returns at 42F3CE, before the chance roll and
//   before the cast. So Param1 = 33 on a hex can never cast anything.
//
//   This plugin makes two independent changes:
//
//   1. ANY TARGET STATE
//      NOPs the `jne` at 51FFC3, so Param1 is registered for every auratargetstate,
//      not only hexpurgedebuff.
//
//   2. RECORD INSTALLER
//      Gives the registrar the hex caster as the installer for the registrations
//      auraeventfunc 36 makes. The engine then stores the caster's unit type and id
//      on each node through its own code path.
//
// D2RLoader 1.3.0 (re-checked against its D2RLoader.exe image and D2RCore.dll):
//
//   The registrar at 438230 is now a loader thunk to D2RCore!RegisterWideSkillEffect
//   (jmp [rip+disp32] and four nops over its first ten bytes), so it can no longer be
//   inline hooked. D2RCore keeps the same ten arguments and the same installer
//   handling: with a unit it stores the unit's type (+0) and id (+8) on the node, with
//   null it stores type 6, id -1.
//
//   Event handlers now come from D2RCore's own table, but its entries for 33 and 36
//   are forwarders that read the game's auraeventfunc table at every call, so
//   auraeventfunc 36 still runs the native function at 51FDA0 and its inline hook
//   still applies. auraeventfunc 33 still runs the native 42F300.
//
//   auraeventfunc 36 installs Param1 through sub_140438470, whose only registrar call
//   is at 438536. Instead of hooking the registrar, the plugin retargets that one
//   call to a near relay into HookRegisterEvent, which calls the registrar thunk
//   with the same arguments. Read from the live 1.3.0 image:
//
//     4384FA  mov  ecx, [rsp+0B0h]        state
//     438501  mov  r9d, r13d              skill id
//     438504  mov  qword [rsp+48h], 0     installer: none
//     43850D  mov  rdx, r14               unit
//     438510  jmp  loader stub            + 6 nops, replaces two stock instructions
//                                         stub: mov  [rsp+40h], ecx        state
//                                               mov  dword [rsp+44h], 0    upper half
//                                               mov  ecx, [rsp+0A8h]       group
//                                               jmp  43851B
//     43851B  mov  [rsp+38h], ecx         group
//     43851F  mov  rcx, r15               game
//     438522  mov  [rsp+30h], eax         auraeventfunc index
//     43852D  mov  [rsp+28h], eax         param
//     438531  mov  [rsp+20h], r12d        skill level
//     438536  call 438230                 <- retargeted
//
//   The stub exists because D2RCore reads two arguments at full 64-bit width: the
//   skill id (r9, stored as a qword; its event handler forwarders refuse to run a
//   node whose skill id has a non-zero upper half) and the state (the ninth
//   argument, stored as a qword and compared as a qword by UnregisterWideEffects when
//   the effects are removed). The hook therefore takes and forwards both at full
//   width, exactly as the caller built them.
//
//   r8d (event id) is loaded just before 4384FA. auraeventfunc 36
//   reaches the registrar only through that helper (`call 438470` at 52005B), and
//   438536 is the helper's only registrar call. The registrar's other callers (42FB5D,
//   43843A, 43861C) are not redirected.
//
// D2RLoader 1.3.1 accepts a call-rel32 patch only when its target is inside
// D2R.exe, and the relay page is not. The call at 438536 therefore goes to a
// 5-byte "jmp relay" trampoline in the int3 run after sub_140438470's ret at
// 43856A (43856B..43856F, the next function starts at 438570), and the
// trampoline jumps on to the relay. A call through a jmp returns exactly where
// the direct call did, with the same registers and stack.
//
// Built against D2R 3.3 (module 140000000.D2RLoader.exe) for D2RLoader 1.3.1 and
// PluginSDK 0.3.0.

// Single-event registrar. Its tenth argument is the installer unit; with a unit it
// stores that unit's type and id on the node, with null it leaves type 6, id -1.
// In D2RLoader 1.3.0 a thunk to D2RCore!RegisterWideSkillEffect.

// Thunk shape: FF 25 disp32 at 438230, then four nops and the untouched tail of the
// old prologue (mov [rsp+18h], rdi / push r14). disp32 locates the loader's import
// slot, moves between loader builds and is not pinned.

// sub_140438470's registrar call and its argument setup, in the live 1.3.0 image.
// The rel32 of the loader's jmp at 438510 moves between loader builds, so it is
// the one gap: 13 bytes at 438504 up to and including the jmp opcode, then 38
// bytes from the six nops at 438515 through `call 438230` (E8 F5 FC FF FF) at
// 438536.

// Prologue of auraeventfunc 36. Sixteen bytes, no rip-relative operands, ends on an
// instruction boundary (the next instruction is `sub rsp, 0A0h` at 51FDB0).
//   48 89 5C 24 10 mov [rsp+10h], rbx / 55 push rbp / 56 push rsi / 57 push rdi
//   41 54 push r12 / 41 55 push r13 / 41 56 push r14 / 41 57 push r15

// The hexpurgedebuff gate: cmp dword [rsp+74h], 0D9h / mov ebp, 1 / jne 520060.
// Checked in full before anything is written, so the NOP can only ever land on this
// exact sequence. `mov ebp, 1` is kept: it is the function's return value.

constexpr std::uint8_t ExpectedHexGate[] {
	0x81, 0x7C, 0x24, 0x74, 0xD9, 0x00, 0x00, 0x00,  // cmp dword [rsp+74h], 0D9h
	0xBD, 0x01, 0x00, 0x00, 0x00,                    // mov ebp, 1
	0x0F, 0x85, 0x97, 0x00, 0x00, 0x00,              // jne 520060
};

