// Holy Freeze Damage
//
// Holy Freeze deals its cold damage to every monster its aura pulses over,
// including the ones monstats.txt marks as unchillable (ColdEffect >= 0, which
// is what prime evils ship with). Those monsters get the damage and nothing
// else: no aura target state, no slow, no shatter roll. Monsters with a
// negative ColdEffect are untouched and keep the full vanilla treatment.
//
// Port of the ESR D2R 2.4 patch set (gate retarget 3886CB, shatter-gate hook
// 38886F, cave 36AD70) to D2R 3.3 on D2RLoader 1.3.0. Every address and byte
// below was read out of the live D2RLoader image and disassembled first.
//
// ---------------------------------------------------------------------------
// The engine, 3.3
// ---------------------------------------------------------------------------
//   srvdofunc table 0x238EA00, slot 81 at 0x238EC88 -> 0x563720, the Holy
//   Freeze server handler. It ends with the range iterator call
//
//     563C93  48 8D 05 E6 D7 FF FF  lea  rax, 561480     ; per-target callback
//     563C9A  48 8B D6              mov  rdx, rsi
//     563C9D  48 89 44 24 30        mov  [rsp+30h], rax  ; iterator arg 7
//
//   so 0x561480 is the callback, and it is reached from nowhere else: that lea
//   is its only code reference in the image.
//
//   0x561480 (2.4 sub_140388650) opens with the gate this plugin is about:
//
//     5614C5  call 48FF40                  ; -> rax, difficulty byte
//     5614CD  movzx r15d, byte [rax]       ; r15 = difficulty, never rewritten
//     5614D1  call 34B9D0                  ; UNITS_GetUnitType(target)
//     5614D6  cmp  eax, 1
//     5614D9  jnz  561515                  ; not a monster -> vanilla path
//     5614EB  call 349860                  ; UNITS_GetClassId -> [unit+4]
//     5614F0  movzx ecx, byte [rsi+106h]   ; pGame+106h = data context
//     5614F9  call 976E0                   ; MonStats record, stride 508
//     5614FE  test rax, rax
//     561501  jz   56150E
//     561503  cmp  byte [r15+rax+1BAh], 0  ; ColdEffect[difficulty], SIGNED
//     56150C  jl   561515                  ; negative -> vanilla path
//     56150E  xor  eax, eax                ; <- site A, 7 bytes
//     561510  jmp  5616C7                  ;    return 0, target skipped whole
//     561515  cmp  dword [rbx+4Ch], 0      ; nPassiveState, aura target state
//     561519  jz   5615BF
//     ...     the state block
//     5615BF  mov  rdx, [rbx+50h]          ; pDamage
//     5615C3  test rdx, rdx
//     5615C6  jz   561675
//     5615D1  call 4494B0                  ; D2Damage copy constructor
//     5615F4  call 560F60                  ; close-range aura damage bonus
//     561612  call 44CE80                  ; SUNITDMG_ExecuteEvents
//     561625  call 44A9B0                  ; SUNITDMG_FinalizeDamage
//     561675  mov  rcx, rdi                ; <- site B, 8 bytes
//     561678  call 34A1E0                  ; UNITS_GetSeed -> unit+28h
//     56167D  ...  LCG, r9d = seed % 100
//     5616AA  mov  edx, 6Bh                ; state 107, shatter
//     5616B5  cmp  r9d, 14h
//     5616B9  setl r8b                     ; the 20% roll
//     5616BD  call 3354C0                  ; STATES_ToggleState(target,107,roll)
//     5616C2  mov  eax, 1
//     5616C7  epilogue, returns
//
//   ColdEffect is the same signed per-difficulty byte as in 2.4, moved from
//   record+412 to record+442 (0x1BA) as the record grew from 476 to 508 bytes.
//
// ---------------------------------------------------------------------------
// Site A: the gate's return 0 becomes a jump into the damage block
// ---------------------------------------------------------------------------
//   56150E, 7 bytes, 33 C0 E9 B2 01 00 00 -> E9 AC 00 00 00 90 90, a jump to
//   5615BF plus two NOP. Same shape as the 2.4 patch at 3886CB, different
//   displacement. The state block is jumped over, so an unchillable monster
//   gets no aura state and no aurastat slow, which is the design: the slow
//   stays gated by ColdEffect, the damage does not.
//
//   Nothing lands inside the window. The only jump into it is jz 56150E at
//   561501, the null-record bail, and it lands on the first byte. That bail
//   now routes to the damage block too, exactly as the 2.4 set did.
//
//   Entering the damage block from the gate is safe: rsi, rdi, rbx, r14 and
//   r15 are all loaded before the gate and are non-volatile, and the damage
//   block is self-contained. 4494B0 is the D2Damage copy constructor and it
//   writes the whole packet including the RAII field at buf+158h that the
//   block's own teardown reads, so this is the same entry the vanilla
//   nPassiveState == 0 path already uses on every pulse.
//
// ---------------------------------------------------------------------------
// Site B: the shatter tail asks whether this target was gated
// ---------------------------------------------------------------------------
//   With site A live the gated target now falls through into the shatter tail,
//   which vanilla never let it reach. The 2.4 set solved that with a cave that
//   re-derived the ColdEffect test; here the same test is re-derived in C++,
//   through the engine's own three calls, and the stub is 81 bytes in a page
//   this plugin allocates.
//
//   561675, 8 bytes, 48 8B CF E8 63 8B DE FF -> E9 <rel32> 90 90 90, resume
//   56167D. Three jumps reach 561675 (5615C6, 56165D and the fallthrough at
//   561671) and all three land on the first byte; nothing lands inside.
//
//   At the tail rdi is the target, rsi is pGame and r15 still holds the
//   difficulty loaded at 5614CD, all three non-volatile and never rewritten in
//   the function. rsp is 16-aligned there (entry + 5 pushes + sub rsp,1F0h), so
//   the stub takes 20h for shadow space, calls, and puts it straight back, and
//   the call to 34A1E0 then runs on the frame's own shadow area exactly as the
//   original instruction did. rax is the only live value at 56167D and it is
//   the seed pointer that call returns.
//
//   Gated targets leave through mov eax,1 / jmp 5616C7, so they never draw from
//   the unit's LCG and never see STATES_ToggleState. That keeps both the engine
//   invariant "unchillable never gets state 107" and the target's seed stream
//   the same as vanilla.
//
//   The stub was assembled with keystone and decoded back with capstone.
//
// ---------------------------------------------------------------------------
// Verified against
// ---------------------------------------------------------------------------
//   D2MOO SKILLS_AuraCallback_HolyFreeze for the gate's logic, Ruff's RVA
//   corpus for 0976E0 (dataContext, classId -> MonStatsTxt*), 34B9D0, 349860,
//   34A1E0, 3354C0, 4494B0, 44CE80, 44A9B0 and Game+106h as the data context,
//   and the ESR 2.4 patch set this replaces.
//
//   soft-hit-removal patches 563BE4..563C29 inside the srvdofunc body; neither
//   site here overlaps it.

// 563C93: the lea that hands 561480 to the range iterator as its callback,
// then mov rdx,rsi / mov [rsp+30h],rax. Proves the function patched below is
// still the one Holy Freeze installs.

// 5614AC: the whole callback prologue and gate, through cmp [rbx+4Ch],0. The
// displaced 7 bytes sit at +62h. Proves the register assignment, the three
// engine calls, the data context at pGame+106h and ColdEffect at record+1BAh.

// ---------------------------------------------------------------------------
// Hook page
// ---------------------------------------------------------------------------
//
// +00  48 83 EC 20              sub   rsp, 20h            ; shadow, stays aligned
// +04  48 89 F9                 mov   rcx, rdi            ; target
// +07  48 89 F2                 mov   rdx, rsi            ; pGame
// +0A  45 89 F8                 mov   r8d, r15d           ; difficulty
// +0D  48 B8 imm64              mov   rax, TargetIsGated
// +17  FF D0                    call  rax
// +19  48 83 C4 20              add   rsp, 20h
// +1D  84 C0                    test  al, al
// +1F  75 1D                    jnz   +3Eh
// +21  48 89 F9                 mov   rcx, rdi            ; the vanilla tail
// +24  48 B8 imm64              mov   rax, 34A1E0
// +2E  FF D0                    call  rax
// +30  FF 25 00 00 00 00        jmp   qword ptr [rip+0]
// +36  dq                       56167D
// +3E  B8 01 00 00 00           mov   eax, 1              ; gated: no shatter
// +43  FF 25 00 00 00 00        jmp   qword ptr [rip+0]
// +49  dq                       5616C7

// ---------------------------------------------------------------------------
// The gate test, re-derived at the shatter tail
// ---------------------------------------------------------------------------
//
// Reached from the stub with the callback's own live registers: rdi, rsi and
// r15. It asks the same three engine functions in the same order as the gate at
// 5614D1..561503, so a target is reported gated exactly when vanilla would have
// dropped it, the null-record bail included.
//
// The difficulty bound is this plugin's own: the gate indexes the record with
// an unbounded byte, which is safe there only because the value is always 0, 1
// or 2. Anything else is treated as not gated, so the shatter tail runs vanilla
// rather than reading past the 508-byte record.

// Immunity Clears DoTs
//
// When a monster becomes immune to every damage type, the life drains that
// are already running on it end on the spot: poison, bleed, burning and any
// other timed effect that drains life through negative life regeneration
// (stat 74, hpregen). Once applied, those drains are no longer poison or
// physical damage, only negative regeneration, so without this plugin they
// keep hurting a boss through its invulnerable phase.
//
// Immunity is judged per drain, against the unit that applied it, exactly the
// way the game's damage code judges a hit from that unit, Sunder included.
//
// 1.1.0: 1.0.0 read the monster's raw resistance stats. Sunder never changes
// those: the game applies it per attacker, inside the damage formula only.
// ESR bosses keep 100+ in every resistance and are broken with Sunder, so
// 1.0.0 saw every boss as permanently immune and ended every drain on the
// frame after it landed.
//
// 1.1.1: the resistance floor, the immunity line, the cap ceiling and the
// Sanctuary state are read from the running game instead of being pinned. ESR's
// resistance floor patch (-1000 at 0x4524C4 and 0x4524E7) changed the pinned
// floor bytes, so 1.1.0 refused to load next to it. The plugin now follows
// whatever values a static patch puts there, the same way the damage code does.
//
// Built for D2R 3.3 on D2RLoader 1.3.1 (PluginSDK 0.3.0). Everything below was
// read out of the live D2RLoader.exe image and D2RCore.dll and disassembled
// before being relied on.
//
// ---------------------------------------------------------------------------
// Where it hooks: the monster stat-regeneration tick, 0x448C00
// ---------------------------------------------------------------------------
//   D2GAME_MONSTER_ApplyStatRegen (game, unit, ...). It is monster event 3:
//   the dispatcher 0x447420 takes the image base (447498 lea r14) and calls
//   [rdi*8+1D1A7A0h+r14] with rcx = game, rdx = unit (447527..44756F). The
//   table holds 0x448C00 for event 3 and 0x42EA80 for event 12; both entries
//   are checked at load.
//
//   The tick runs every frame while the monster's life regeneration is not
//   zero and is the only place negative regeneration removes a monster's
//   life. It reads the unit's stat 74 first (448C20..448C34). The plugin runs
//   before it, so the tick already reads the regeneration without the drains
//   that were ended.
//
// ---------------------------------------------------------------------------
// What counts as a drain
// ---------------------------------------------------------------------------
//   Poison (0x4518C0), burning (0x451380) and every state applied through
//   D2RLoader's timed-state function (0x433D20, how the bleed plugin applies
//   bleed) build the same kind of effect: a child stat list with timer flag 2,
//   an end frame, stat 74 = -damage, a removal callback and an event 12 for
//   the end frame. The plugin takes every child list in the unit's merged
//   chain (unit+88h, +90h, next +68h, as 0x2F5940 walks it) with
//     flags (+1Ch): not extended (sign bit), timer flag 2, no custom-timer
//                   flag 8000h, no unmerged flag 2000h
//     own stat 74 below 0, read with the list stat reader 0x2F5DF0 the poison
//     applier itself uses.
//
// ---------------------------------------------------------------------------
// Who applied it
// ---------------------------------------------------------------------------
//   STATLIST_AllocStatList 0x2F7300 (flags, end frame, type, id) stores the
//   source's unit type at +8 and unit id at +0Ch; 0x2F6E30 / 0x2F6E20 read
//   them back. Poison, burning and the timed-state function all pass the
//   attacker; for a missile hit 0x436E90 has already swapped the missile for
//   its owner. The regen tick's own kill credit (448E1A..448E2E) finds the
//   killer exactly this way: SUNIT_GetServerUnit 0x48FE80 (game, type, id).
//
// ---------------------------------------------------------------------------
// What counts as immune: SUNITDMG_ApplyResistancesAndAbsorb 0x4523E0
// ---------------------------------------------------------------------------
//   SUNITDMG_CalculateTotalDamage 0x44DF10 builds a context at rsp+40h
//     +00h game  +10h attacker  +18h defender
//     +24h 1 when the defender is a monster and not a hireling (44DFAE)
//   and twelve 40h-byte records from rbp-80h (44EC40 walks them):
//     +08h resistance stat  +0Ch max stat  +10h -enemy-res stat
//     +14h Sunder stat
//   For the six damage types (44E14D..44E454, constants at 1D1ACE0 and
//   1D1AD20):
//     physical   36  -1   366 in Reign of the Warlock games, else -1   192
//     magic      37  38   358 in Reign of the Warlock games, else -1   193
//     fire       39  40   333   189
//     lightning  41  42   334   190
//     cold       43  44   335   187
//     poison     45  46   336   191
//   ("Reign of the Warlock game" is 0x4040B0: game data context == 3.)
//   For each record the resolver does, with rsi = context, r14 = record and
//   ebp = 0 (4523F5):
//     45242A  resistance = 0x2F5020(defender, record+8, 0)
//     452444  resistance = Sunder 0x44F6D0(context, record, resistance)
//     452452  resistance = -enemy-res 0x44F8B0(context, record, resistance)
//     452481  0x092A10 decides a floor; it is "xor al,al / ret" in this
//             build, so that floor never applies
//     4524C0  a value of 0 or less becomes max(value, floor) and is final;
//             the floor is the imm32 at 4524C5 (-100 stock, -1000 with ESR's
//             resistance floor patch)
//     45249C  the player cap, skipped when context+24h is set; it ends at
//             min(..., ceiling), the imm32 at 4524DE (95 stock)
//     4524F8  physical: 0 if the attacker has the Sanctuary state (imm32 at
//             452504, 47 stock) and the defender is undead (0x3AF2C0)
//     452547  damage *= line - min(resistance, line), line = imm32 at 452548
//             (100 stock)
//   So a monster is immune to a damage type from that attacker exactly when
//   the result reaches the line. The four immediates are read from the
//   running game each time; only the instructions around them are pinned. The plugin builds the same context and record
//   and calls the same Sunder and -enemy-res functions, then applies the
//   Sanctuary rule. Sunder reads context +0, +10h, +18h, +24h and record +8,
//   +14h; -enemy-res reads context +0, +10h, +18h, +24h and record +8, +10h
//   (44F6D0.., 44F8B0..); neither reads anything else of either.
//   D2RCore's ApplyResistanceComponentWithPrimeEvilThreat, which now calls
//   0x4523E0 for the game, only adds Prime Evil threat bookkeeping afterwards.
//
//   Capped defenders end at or below the ceiling, so while the ceiling is
//   under the line they are never immune: hirelings (0x3AF240 non-zero, so
//   context+24h is 0 and the player cap applies), and, while the Summon
//   Resist Cap plugin is active (its jmp at the 45249C gate), allied monsters:
//   monstats.txt Align, a byte at record +87h (column parser 39DE8E /
//   39E035), equal to 1, which is what that plugin caps. If a patch ever
//   raises the ceiling to the line, the plugin says so once in the log and
//   still leaves capped defenders alone.
//
// ---------------------------------------------------------------------------
// How a drain is ended: the game's own state-expiry event
// ---------------------------------------------------------------------------
//   Event 12 is 0x42EA80: ExpireUnitStatLists(unit, [game+170h], 1.0), a
//   loader thunk at 0x2F82F0 to D2RCore ExpireWideUnitStats. With a frame, it
//   removes every timer-flag-2 list (no 8000h) whose end frame is at or before
//   that frame: it takes the list's stats off the unit, runs the list's
//   removal callback (poison's stacking-aware 0x4505E0, the default 0x436240,
//   or D2RCore's default), then frees the list. The callbacks turn the state
//   off and tell clients, so the overlay clears.
//
//   The plugin sets each qualifying drain's end frame to the current frame
//   with the game's own setter 0x2F7AB0 and runs event 12 for the unit: what
//   happens when the drains run out by themselves. Nothing of the removal is
//   reimplemented. Afterwards it checks that the drains it ended are gone.

// 44F6D0: Sunder (context, record, resistance): record+14h, context+24h,
// context+10h through 2F5020, record+8 and context+18h through 2F48C0,
// context+0 -> game+106h.

// 44F8B0: -enemy-res (context, record, resistance): record+10h, the 092A10
// switch, "resistance >= 100 and context+24h set -> unchanged", context+10h,
// record+8, context+18h.

// 4524F8: cmp [record+8], 24h (physical) / jne / mov rcx, attacker;
// 452503: mov edx, imm32 (the Sanctuary state, 452504, not pinned);
// 452508: call STATES_CheckState / test / je / mov rcx, defender / call the
// undead test / test / cmovne ebx, ebp (0) / mov ecx, ebx.

// 452547: mov ecx, imm32 (the line, 452548, not pinned); 45254C: cmp ebp,ecx /
// mov eax,ecx / cmovl eax,ebp / sub ecx,eax / mov ebp,eax: damage *= line -
// min(resistance, line).

// Hirelings are capped like players by the game itself (context+24h is 0),
// and allied monsters are capped by the Summon Resist Cap plugin while its
// jump sits on the cap gate. A capped defender stays at 95 or below.

struct LiveRules {
    std::int32_t floor = 0;      // 4524C5
    std::int32_t ceiling = 0;    // 4524DE
    std::int32_t sanctuary = 0;  // 452504
    std::int32_t line = 0;       // 452548
};

// Invincible State
//
// While a player, mercenary, monster or summon has one of the configured
// states, it cannot lose life by any means and cannot die from damage.
// Healing still works.
//
// Everything below was read out of the D2RLoader 1.3.1 process dump (md5
// 8af7a47ce9077de0378c69af2930854d) with IDA. Every game address the plugin
// uses is guarded by a byte witness at load.
//
// ---------------------------------------------------------------------------
// The one funnel every life write goes through
// ---------------------------------------------------------------------------
//   D2RLoader moved the stat store into D2RCore: the game's STATLIST_SetUnitStat
//   0x2F7D10 is a 10-byte import thunk, jmp [rip+3B32532h] / nop x4, whose
//   pointer at 0x3E2A248 leads to D2RCore!SetWideUnitStat (unit, stat, value,
//   layer). Every life change the game makes is a call of that thunk:
//     0x44D093  the damage commit (SUNITDMG_ExecuteEvents): every hit, thorns
//               and reflected damage, corpse explosions, everything a missile,
//               melee or skill deals; Alchemy's relay there calls it too
//     0x42E6D1  the player regen tick: poison, burning and every other
//               negative hpregen on a player (the tick never goes below 1 life)
//     0x448D4C  the monster regen tick: the same for monsters and mercenaries
//   The plugin swaps that one pointer for its own function, which calls what
//   was there before (D2RCore, or the next plugin that swapped it): a write of
//   stat 6 (hitpoints, layer 0) that would lower the life of a unit with one
//   of the states writes its current life instead. Other plugins swap other
//   pointers of the same table the same way (Monster Regen Start, Charm
//   Dedup, Loot Filter); none uses this one, and the swap chains in any order.
//
// ---------------------------------------------------------------------------
// The two places that decide death themselves
// ---------------------------------------------------------------------------
//   The damage commit reads life back after the write and marks the unit as
//   dying only when it is 0, so a kept life means no death. The player regen
//   tick never lets life drop under 256 (1 life). The monster regen tick,
//   0x448C00, decides death on its own value:
//     448D35  cmp esi,1 / mov r14d,r15d / mov rcx,rdi / cmovge r14d,esi
//     448D42  xor r9d,r9d / mov r8d,r14d / lea edx,[r9+6] / call 2F7D10
//     ...
//     448D9D  test r14d,r14d / jne 448F87   ; 0 -> the poison or burn kill
//   So 448D45 (mov r8d,r14d / lea edx,[r9+6], 7 bytes) becomes a call to a
//   relay that asks the plugin for the life to use and puts it in both r14d
//   (the value the death check reads) and r8d, then replays lea edx. rdi is
//   the monster. Monster Life Cap patches 448D19..448D1F, before this.
//
// ---------------------------------------------------------------------------
// Not damage, left alone
// ---------------------------------------------------------------------------
//   Life spent as a skill cost goes through the stat add 0x2F34F0 (Blood Magic)
//   or inside D2RCore, not through the writer above, so costs still apply.
//   Mana burn, stamina drain, freezing, knockback and hit recovery are not
//   life loss and still happen; the attacker's life and mana leech, worked out
//   from the damage of the hit, still happen too.
//
// ---------------------------------------------------------------------------
// ABIs (x64)
// ---------------------------------------------------------------------------
//   SetWideUnitStat     (unit, stat, value, layer)
//   0x2F5020            STATLIST_GetUnitStat (unit, stat, layer) -> int32 (thunk)
//   0x3351B0            STATES_CheckState (unit, state) -> int32; asserts on an
//                       id at or past the states count, which is
//                       [0x300A90(0x34A0E0(unit)) + 298h]

// Relay entered by the call at 448D45 (rdi = the monster, r14d = its new life):
//   push rcx / sub rsp,20h / mov rcx,rdi / mov edx,r14d / call [slot RegenLife]
//   add rsp,20h / pop rcx / mov r14d,eax / mov r8d,eax / xor r9d,r9d
//   lea edx,[r9+6] / ret

// =============================================================================
//  Item Quantity  -  celestialrayone.item-quantity
//
//  A stat on the killer adds extra picks to the monster's own treasure class,
//  so monsters drop more of what they already drop. Port of the 2.4 patch set
//  (hook 2F9317 + caves 1A22E8 / 36ABA0 / 36ABE0) to D2R 3.3 under D2RLoader
//  1.3.0, as a plugin: one 6-byte hook, one stub, everything else in C++ and
//  in the config file.
//
// -----------------------------------------------------------------------------
//  WHERE THE PICKS ARE DECIDED
// -----------------------------------------------------------------------------
//  TREASURECLASS_GenerateDrops 0x441300 resolves the treasure class row and
//  calls the roll at 0x4404F0 (2.4 sub_1402F9210). The roll keeps a stack of
//  treasure-class frames at rbp+0x80, stride 32:
//
//      +0x00  the treasureclassex record
//      +0x08  the working pick counter, decremented once per item dropped
//      +0x18  the depth of this frame
//
//  Frame 0 is the monster's own treasure class, so its counter is [rbp+0x88].
//  It is filled at 0x4406A1 with max(abs(Picks), 1), Picks being the dword at
//  record +0x18 (it was +0x0C on 2.4), and the drop loop starts one
//  instruction later at 0x4406A7. Adding to the counter at exactly that point
//  gives the monster extra picks from its own list, once per drop, which is
//  what the 2.4 cave did.
//
//  Arguments are already homed by then: the monster at [rsp+0x58], the killer
//  at [rbp-0x80], the game at [rsp+0x70], and the record is still in rbx.
//
// -----------------------------------------------------------------------------
//  WHAT THIS BUILD DOES DIFFERENTLY FROM THE 2.4 CAVES
// -----------------------------------------------------------------------------
//  Two of the three 2.4 caves are not needed here.
//
//  Cave B walked a summon's stat list by hand to find its owner. The roll
//  itself resolves a non-player killer through 0x4A53C0 and uses the result to
//  credit the owner's magic find, so this plugin calls the same function: it
//  checks the unit is a monster, reads MonsterData at +0x10, the block at
//  +0x30, and looks the owner up by context/type/id.
//
//  Cave A's itemstatcost bounds checks are not needed either: 0x2F5020 is the
//  (unit, statId, layer) stat entry the roll already uses, so reading the stat
//  off the killer is one call with no table anchors to keep in sync.
//
//  Kept exactly: picks are only ever added when the record's Picks is
//  POSITIVE. A negative Picks is a guaranteed-drop list whose counter is used
//  as an index, and inflating it would index out of range.
//
//  THE STAT IS A MULTIPLIER OF THE MONSTER'S OWN PICKS by default: with
//  Picks 5 a stat of 100 adds 5 more, so the monster rolls its list ten times
//  instead of five. The 2.4 meaning of the stat, a percent chance of ONE
//  extra pick, is still available as mode = "chance".
//
//  THE ENGINE CAPS ITEMS PER DROP AT SIX on the monster path. The roll stores
//  that limit at [rsp+0x68] (default 6 when the caller passes no array of its
//  own, which the monster death path at 0x447DF0 does not) and re-reads it for
//  every item at 0x441157 before deciding to stop. Extra picks past the cap
//  produce nothing, so max_items raises it from the same hook, and only when
//  the caller supplied no array of its own, since raising it for a caller with
//  a fixed-size array would overflow that array.
//
//  Kept exactly: the percent roll never calls the game RNG. It hashes the
//  monster's own drop seed (unit +0x28 / +0x2C through 0x34A1E0), so no draw
//  is consumed and no existing drop behaviour shifts. Deterministic per
//  monster, which is how D2 drops already work.
//
// -----------------------------------------------------------------------------
//  THE STUB
// -----------------------------------------------------------------------------
//  The six bytes at 0x4406A1 become jmp rel32 + nop into a page the plugin
//  allocates in reach of the image. The stub replays the stolen store, saves
//  every volatile register (rax is live across the site), calls the C++ entry
//  with monster, killer, record, &counter and game, and jumps back to
//  0x4406A7. It is entered by a jump, never by a call, so the C++ entry is
//  noexcept and does nothing that can raise: every pointer is checked and
//  every game function it calls is guarded against the arguments that make it
//  assert.
//
//  Console command "itemquantity" shows the settings, what is installed and
//  the counters. Settings: d2rloader/config/celestialrayone.item-quantity.toml
// =============================================================================

//  mov [rbp+88h], ecx          replay the stolen store
//  push rax/rcx/rdx/r8/r9/r10/r11/rax      rax is live across the site
//  mov rcx, [rsp+98h]          monster ([rsp+58h] plus the 0x40 of pushes)
//  mov rdx, [rbp-80h]          killer
//  mov r8, rbx                 treasure class record
//  lea r9, [rbp+88h]           the pick counter
//  mov rax, [rsp+0B0h]         game ([rsp+70h] plus 0x40)
//  lea r10, [rsp+0A8h]         the per-drop item cap ([rsp+68h] plus 0x40)
//  mov r11, [rbp-60h]          the caller's item array, null on monster drops
//  sub rsp, 40h                shadow space plus three stack arguments
//  mov [rsp+20h], rax / [rsp+28h], r10 / [rsp+30h], r11
//  call [rip -> ApplyBonusPicks]
//  add rsp, 40h / pops / jmp [rip -> 4406A7]

// =============================================================================
//  Jeweler  -  celestialrayone.jeweler
//
//  The Jeweler perks of the specialization system that need code:
//    Arcane Infusion   +10% to the modifiers of the character's amulet
//    Rings of Power    +5% to the modifiers of the character's rings, pooled
//    Amplification     +5% to the modifiers of every jewel and gem socketed in
//                      anything whose stats reach the character, pooled
//    Prismatic Resonance  +6% more to every socketed gem for each different
//                      gem color socketed in anything that counts, pooled
//                      together with Amplification
//    Mirrored Ring     one ring only, mirrored in the other ring slot: its
//                      modifiers are doubled and the other slot shows it as a
//                      ghost, the way a two-handed weapon shows in the shield
//                      slot
//    Six Peas in a Pod +6% more to every socketed gem for each gem of its
//                      color socketed in the same item, pooled with the rest
//    Primordial Jewels a socketed jewel gains one modifier of the perfect gem
//                      its graphic shows, fixed per jewel by its saved seed
//    Steady Pliers     +20% to the modifiers a gemword adds (never the gems'
//                      own), pooled with the rest
//  A perk counts while the character's own value of its stat is above 0.
//  Next to the perks, stats that are not perks:
//    Gem Effect        each [[gem_effect]] stat raises the socketed items of
//                      its types by the character's total value of the stat,
//                      in percent, pooled with the gem perks; with own_sockets
//                      by the value of the item they sit in, there only; a
//                      block can also be limited to uniques it names
//
//  Built for D2R 3.3 under D2RLoader 1.3.1 (D2RCore 1.3.1-beta). Every native
//  function the plugin calls was read out of the dumped D2RLoader 1.3.1 image
//  and decoded before being relied on. Byte witnesses pin each of them (the
//  function's own body, or the game's own call to it), and the stat array
//  layout is pinned against D2RCore!VisitWideUnitStats. On a different build
//  nothing is installed and the console command says why. The plugin patches
//  no game code: it only calls game functions from D2RLoader's thread service.
//
// -----------------------------------------------------------------------------
//  HOW A BONUS REACHES THE CHARACTER (the blacksmith plugin's mechanism)
// -----------------------------------------------------------------------------
//  Each item that earns a bonus carries one extra plain stat list of the
//  plugin's, attached to the item the way 0x43EF10 gives an item its
//  quest-difficulty list (43F407..43F487):
//      2F7300  alloc (10000h, 0, owner type 4, item id)
//      2F2CB0  attach (item, list, 1)       D2RCore AttachWideStatList, mode 1
//      2F7C00  set (context, list, stat, value, layer)
//  and removed with 2F7920 unlink (item, list) + 2F4180 free (context, list).
//  The list is a child of the item, so the item's tooltip shows the raised
//  values and its stats reach the character exactly when the item's do.
//  Never saved or sent: the item serializer only writes lists with flag 40h or
//  2040h. Server and client keep their own lists, built from the same items,
//  so combat (server) and the tooltips and character sheet (client) agree.
//
// -----------------------------------------------------------------------------
//  WHICH ITEMS COUNT
// -----------------------------------------------------------------------------
//  An item's stats reach the character exactly while the item's stat list is
//  merged into the character's. STATLIST_GetOwner 0x2F8120 (item, &mode)
//  returns the unit an item's list is merged into (the unit of the parent list
//  at ex +78h, read at the parent's +A0h), or null. The game's own refresh
//  0x46F220 walks the character's inventory with INVENTORY_GetFirstItem
//  0x388C10 / INVENTORY_GetNextItem 0x38ABA0 and re-merges every item 0x2F8120
//  returns an owner for (D2RCore AttachWideUnitStats). The merge leaves out the
//  inactive weapon set (body locations 11 and 12), 0x475140 leaves out broken
//  items, and a charm is merged only when ITEMS_IsCharmUsable 0x36AE00 allows
//  it (ESR's charm dedup included). So an item counts when 0x2F8120 returns the
//  character: equipped gear in the active set, and every charm the game lets
//  count, wherever its page is. Mode 0 (a dual-wielder's second weapon) still
//  counts: the merge then only holds back its damage stats for its own attacks.
//
// -----------------------------------------------------------------------------
//  AN ITEM'S MODIFIERS
// -----------------------------------------------------------------------------
//  An item's modifiers are read from the stat lists that hold them, never from
//  its full stats array (ex = unit +88h, +A8h, count +B0h, the array
//  D2RCore!VisitWideUnitStats reads, and the one 0x2F5020 reads). That array
//  is the engine's cache of each stat's total, and for a stat with an
//  itemstatcost op the engine stops keeping it current: when such a stat
//  changes, its own total is committed only while every op target on the same
//  item is 0, or while the op does not apply there (D2MOO sub_6FDB64A0, D2RCore
//  +3DBEB0, see the enhanced-damage-fix plugin). Otherwise the total keeps the
//  value it had before, so a bonus written next to the stat never shows in it.
//  passive_summ_mastery_total (op 1) on a ring that also has
//  passive_summ_mastery kept the 10 it had when the ring was loaded while this
//  plugin took its own addition back out of it every pass: 10, 20, 10, 20 at
//  100%, and a swing that grew without end above 100%. The op 13 stats
//  (item_armor_percent, item_maxdamage_percent, item_mindamage_percent,
//  item_maxdurability_percent) on an item with the base value they multiply,
//  and the op 4 and 5 per-level stats on an equipped item, are held back the
//  same way. The array also holds what the engine derives through an op (a
//  weapon's enhanced damage on its base damage, per-level defense), which is
//  not a modifier of the item at all.
//
//  The values come from the item's active child chain instead (ex +90h, next
//  at +68h), summed the way the engine sums them for the item: the stats of
//  every plain list there (+30h, count +38h, 16-byte entries {layer u32, stat
//  u16 at +4, value i32 at +8}), and for every item socketed in it (an extended
//  list in the chain, flag 80000000h) that item's full stats (+A8h, count
//  +B0h), which is what the engine adds into the host for it; both are the
//  layouts the pinned VisitWideUnitStats reads. A socketed item's stats never
//  change after it is socketed, so its totals are current. A list with flag
//  2000h is linked into the other chain (+98h) by the D2RCore attach and counts
//  for nothing, as for the engine. The item's own base values (+30h of the ex
//  itself) are not modifiers and stay out. A pair's modifier value is
//      list total - every plugin bonus list on the item
//  where a plugin bonus list is any plain list with flag 10000h in the item's
//  chain: the jeweler's own list and any other plugin's (the blacksmith carries
//  Unbreakable Gear and Extended Reach on a ring or the amulet when no armor
//  piece is worn). No bonus ever feeds on itself or on another plugin's bonus.
//  The total holds the item's affixes, unique and set item modifiers, the
//  active set bonus lines (state lists on the set item, switched by 0x3D62C0
//  through D2RCore SuppressWideStateStats), a runeword's or gemword's list,
//  and the items socketed in it.
//
// -----------------------------------------------------------------------------
//  SOCKETED JEWELS AND GEMS
// -----------------------------------------------------------------------------
//  Socketing (0x46EF30 -> 0x475140) writes a gem's gems.txt modifiers into the
//  gem's own modifier list (0x3D3670 mode 2, list flag 40h); a jewel keeps its
//  own affixes. The socketed item is then merged into its host, so 0x2F8120 on
//  it returns the host. The host's sockets are its own inventory
//  (UNITS_GetInventory 0x34A360 on the item, walked with 0x388C10/0x38ABA0).
//  Amplification reads each jewel's and gem's own modifiers from the jewel or
//  gem itself, so the host's modifiers and a gemword's bonus never count. The
//  bonus goes on the host, whose tooltip shows it.
//
//  MIRRORED RING (client side): the inventory slot widget's draw 0x2C9940
//  fetches the slot's item, then the item of the paired slot through
//  0x15F220 (4 <-> 5 only), and when the slot is empty and that item is
//  two-handed (GetItemHandednessForUnit == 2, 2C9C06) it draws it in this
//  slot with the background over it: the ghost. Its tooltip is that item's.
//  The plugin redirects that pairing call and that handedness call: for the
//  blocked ring slot, empty, with a ring in the allowed slot and the local
//  character holding the perk, the pair is the allowed slot and the ring
//  counts as two-handed. Every equip, pickup and swap of a body location goes
//  through 0x15C600 (held item, slot, ...), called from five places (2AA937,
//  2AAA79, 2CABDC, 2CAC6C, 2CB0AB); the plugin redirects all five: on the
//  blocked slot a pickup takes the ring from the allowed slot, a held ring
//  swaps with it, and with no ring there the held ring is refused with the
//  game's own "Impossible" (106B70 (player, 14h), as 0x15C600 does for an
//  item that does not fit). The slot's highlight (36BB10 at 2C9BA5) follows.
//  Nothing is sent for the blocked slot, so the server never needs a check.
//  Every redirect is a five-byte call to a near relay page, and every site is
//  byte-checked first; a mismatch leaves the client side off.
//
//  MIRRORED RING (both sides): while the allowed slot holds a ring that
//  counts and the blocked slot is empty, the ring's bonus list carries
//  bonus_percent (100) of every modifier it has, as a second identical ring
//  would; its Rings of Power share is taken twice, and the jewels and gems in
//  it are pooled twice by the gem perks.
//
//  Prismatic Resonance counts the colors of the gems socketed in the items
//  that count (a gem's color is the first color type it matches through
//  0x373890) and gives every socketed gem percent_per_color times that many
//  colors. Its percent is added to Amplification's for each gem, so both are
//  one numerator in the same pool and are rounded once. It uses Socketed
//  Gems' stats list. Six Peas in a Pod counts, per item, the gems of each
//  color in it and gives each gem percent_per_gem times the count of its color
//  there.
//
//  TOOLTIPS: an item's blue lines are drawn from one list of the item: the
//  first in its chain with state 0 and flag 40h (the finder 0x2F5A00), plus
//  the runeword list and that same list of every item in its sockets. The exe
//  draws them in 0x2DA0E0, and D2RCore's own tooltip builder (the one with
//  stat ranges, BuildItemTooltipWithStatRanges) draws them without ever
//  calling 0x2DA0E0, so no hook on the exe covers every tooltip. A plugin list
//  (flag 10000h) is never drawn. So on the CLIENT the bonuses are written into
//  that very list: the plugin remembers what it added to it and the value each
//  stat had right after, and treats its additions as gone the moment the list
//  is a different one or any of those values changed (the client rebuilt the
//  item from a server packet). Its own math always takes its additions back
//  out first, so a bonus is never raised by itself. The server keeps its
//  separate never-saved lists: client units are only ever drawn, never saved.
//
//  PRIMORDIAL JEWELS: a jewel's look is its graphic variant (item data +5Eh,
//  rolled from the item's seed when it is made, saved as 3 bits), and the
//  sprite number is that variant plus 1. The variant picks a perfect gem; its
//  gems.txt row (tables +1658h, 192 bytes) is the one whose +28h holds the
//  gem's items.txt row (the loader turns the "code" column into that row,
//  and D2RCore's LinkGemRows links items to gems by it), and holds nine mods, weapon, helm and
//  shield, each { property id + kind << 16, param, min, max } from +30h, 10h
//  apart. Kind 1 is a propertygroups.txt row (tables +258h, 200 bytes) whose
//  eight members { prop, parmin, parmax, modmin, modmax, chance } start at +8,
//  18h apart. Every property met this way (groups opened, members whose
//  property sets an excluded stat, gemmaster, left out) is one candidate, and
//  the jewel's starting seed (unit +30h, saved with the item) picks one, so the
//  same jewel always gets the same one. Only the SERVER has that seed: the
//  item decoder (0x378860) reads the 32 seed bits only when its save flag is
//  set ([rbp+67h] at 378C3D), and the items the client is sent carry none, so
//  every client copy of a jewel has the same +30h. The server therefore makes
//  the pick and records it by unit id (a client item has its server item's
//  id); the client applies exactly that record and shows nothing for a jewel
//  the server has not picked for (a client joined to a remote host). The game itself applies it: 0x3D5060
//  (context, 7, 0, jewel, prop, 0, 0, 0, prop, state 0, flag 10000h, 0), as
//  the cube applies a recipe mod but with the plugin's flag, so the stats land
//  on a list of the jewel's own that is never saved (0x3D5230 finds or makes
//  it). A min-max value outside the range funcs 15-17 is rolled from the seed
//  first, so the game rolls nothing. Arcane Infusion, Rings of Power and
//  Mirrored Ring see it through the host item's total; Amplification adds it
//  to the jewel's own modifiers. The list goes when the jewel leaves its
//  socket, the perk is lost or the plugin unloads.
//
//  STEADY PLIERS: a runeword's modifiers (runes.txt T1 codes, propertygroups
//  included) live in one list on the item, state 171 with flag 40h, which
//  2F5B80 (item, 171, 40h) finds by its state (2F58C0); the runes' or gems'
//  own modifiers stay on the socketed items. An item is a gemword when it has
//  that list and every item in its sockets is one of socket_types (gems).
//  The list's stats take bonus_percent into the gem pool on that item.
//
//  GEM EFFECT: one stat per [[gem_effect]] block (a stat named in several
//  blocks takes all of their types, so it counts once per item). A stat's
//  value is the character's total, read the way stat('x'.accr) reads it
//  (0x2F5020 on the character): gear, charms, skills and the socketed items
//  themselves, plus this plugin's bonuses on the character's items (a
//  mirrored ring's second copy of the stat), none of which depends on gem
//  effect. Each socketed item adds the values of the stats whose types it
//  matches to its percent in the gem pool, the way Prismatic Resonance's
//  joins it, so they are one numerator, rounded once. No gem effect stat is
//  ever raised by Gem Effect: an item holding one would otherwise raise its
//  own percent, or through another block the other stat's, pass after pass.
//  An item's total percent is floored at -100, so a negative value takes its
//  modifiers down to 0 and never past it.
//
//  A stat whose block has own_sockets takes its value from each host
//  instead: the host's own value, its total (0x2F5020 on the host) less its
//  base and every plugin bonus list on it, the way AN ITEM'S MODIFIERS reads
//  a modifier. That holds the host's affixes, its unique, set and runeword
//  modifiers and the items socketed in it, and never a plugin bonus (a
//  mirrored ring's second copy of the stat, or the Amplification share a
//  host carries for a jewel's copy of it), so the value never feeds on gem
//  effect. It raises only the items socketed in that host, in the same gem
//  pool, so it is rounded once with everything else. One stat has one
//  meaning: a stat named in several blocks takes the first one's own_sockets.
//
//  A block's host_uniques limits it to the items socketed in those uniques:
//  the host's quality is unique (7, ITEMS_GetItemQuality 0x36CF60, item data
//  +0) and its file index (0x36CE70, item data +34h) is one of the rows
//  named, the same two calls the unique pick 0x443910 makes to test an item
//  against a uniqueitems.txt row. The names are the index column, looked up
//  in the table of the character's own data context the way 0x443910 reads
//  it: rows at tables +13C8h, count +13D0h, 15Ch (348) bytes each (443A70,
//  443B82), the index a string of 31 at +2 (its column in the compiler
//  0x31F1D0). The percent is still the character's total of the stat. A
//  name no row has matches nothing, so such a block never counts in any
//  other item.
//
// -----------------------------------------------------------------------------
//  POOLING
// -----------------------------------------------------------------------------
//  Rings of Power and Amplification pool every counting item: per (stat, layer)
//  the numerators own * percent are summed and the bonus is sum / 100, rounded
//  toward zero like the game's own percents. It is split back over the items:
//  each gets floor(n / 100), and the points still missing go to the items with
//  the largest remainders (ties to the earlier item), so the shares add up to
//  the pooled bonus exactly and each tooltip shows about its own part. Stats
//  that only change their own item (itemstatcost op 13: enhanced defense,
//  enhanced damage, durability; 0x2F8AD0 op 13 multiplies the owner item's own
//  base) pool per item instead. An equipped item that does not count is
//  computed on its own (its tooltip shows its bonus) and adds nothing to the
//  pools.
//
// -----------------------------------------------------------------------------
//  ITEM TYPES
// -----------------------------------------------------------------------------
//  ITEMS_CheckItemTypeId 0x373890 (item, type) tests the item's types in the
//  itemtypes equivalence table, so a parent code covers its children.
//  itemtypes.txt codes are resolved against the live table (tables + 1348h,
//  count + 1350h, rows of E8h bytes, code at +0).
//
//  Passes run on D2RLoader's thread service: on the host's game thread every 4
//  game updates for every player in the game (the server client registry), and
//  on the UI thread every 100 ms for the local player.
//
//  Console command "jeweler" shows the settings, what is installed and
//  counters; "jeweler items" lists the bonus on each item of the character.
//  Settings: d2rloader/config/celestialrayone.jeweler.toml
// =============================================================================

// 0x43EF10 giving an item its quest-difficulty list: 2F5B80 find, 34A330 unit id,
// 2F7300 alloc (40h, 0, 4, id), 2F2CB0 attach (item, list, 1), 2F7C00 set (context, list, 356, value, 0)
// 43F407..43F487 (128 bytes)

// D2RCore!VisitWideUnitStats (1.3.1-beta), whole body 832560..8325F6: ex =
// unit +88h; extended (+1Ch < 0) -> array +A8h, count +B0h, else +30h / +38h;
// entries of 10h bytes (add r15,10h). The same entries are what the attach
// (3DA4F0) adds up and the stat readers (3D8790, 3D8BD0) search.

// Tooltips (see the header)
// 0x2F5A00 (unit, state, flags): the first list of the unit's chain (+90h) with that state (+20h) and a flag (+1Ch) in common
// 2F5A00..2F5A99 (153 bytes)

// Primordial Jewels (see the header)
// 0x3D3420, the cube's property apply: 3D5060 (context, 7, 0, item, prop, 0, 0, 0, prop, state 0, flag 40h, 0)
// 3D3420..3D347F (95 bytes)

// Gem Effect, host_uniques (see the header)
// ITEMS_GetItemQuality (item): item data +0, 2 for a unit that is not an item
// 36CF60..36CFD1 (113 bytes)

// Mirrored Ring, client side (see the header)
// InventorySlotWidget draw 0x2C9940: the paired slot (call 15F220 at 2C99DD), then its item
// 2C99D5..2C99EC (23 bytes)

// draw: an empty slot draws the paired two-handed item as a ghost
// (call GetItemHandednessForUnit at 2C9C06, == 2, then draw 2A72D0)
// 2C9BFA..2C9C16 (28 bytes)

struct EffectRuleIds {
    std::vector<std::int32_t> types;
    std::vector<std::int32_t> hosts;    // uniqueitems.txt rows of its host_uniques
    bool                      anyHost;  // the block names no unique: any item
};

// A uniqueitems.txt index in these tables: the name exactly as written, else
// one that differs only in letter case (the log says so). -1 when no row has
// it, or when the table's layout could not be verified.

// What an item's stat lists hold, per (stat, layer) pair (see AN ITEM'S
// MODIFIERS): every list in its active child chain (+90h, next at +68h), and
// for an item socketed in it (an extended list in the chain) the full stats the
// engine itself adds into the host. Never the item's base values, never what
// the engine derives through an op on the item, never a total it stopped
// keeping current.

struct Witness {
    std::uint64_t       rva;
    const std::uint8_t* bytes;
    std::uint32_t       size;
    const char*         name;
};

struct Pin {
    std::uint64_t       rva;
    const std::uint8_t* bytes;
    std::size_t         size;
    const char*         what;
};

// Large Item Transfer
// Plugin id: celestialrayone.large-item-transfer
//
// ---------------------------------------------------------------------------
// The bug
// ---------------------------------------------------------------------------
//   The server sends every item to a client in one item message. Both senders
//   give the item's data 244 bytes of room:
//
//     0x479CD0  SendItemAction9C  SerializeItem(item, buffer, 244, 0, 0, ...) + 8
//     0x479EA0  SendItemAction9D  SerializeItem(item, buffer, 244, 0, 0, ...) + 13
//
//   The length field of both messages is one byte, and the client's message
//   reader (0x644870) accepts a 0x9C message only up to 252 bytes and no
//   message above 512. When an item needs more room, the serializer reports
//   0 bytes and the message goes out with an empty item. The client cannot
//   read it:
//     - put into a container (0x9D action 4, handler 0x1C4300): the new item
//       is freed and then passed on as NULL, and the placement routine reads
//       address 0 (crash at 0x34E237);
//     - other handlers drop the item on the client while the server keeps it.
//   D2RCore's extended item format writes 16-bit stat ids and ESR's raised
//   Save Bits make a median stat cost about 30 bits, so an item reaches the
//   limit at roughly 55 stats.
//
// ---------------------------------------------------------------------------
// The fix
// ---------------------------------------------------------------------------
//   Server, only inside the two senders above (recognised by the return
//   address of their SerializeItem call):
//     - D2RCore!SerializeItem writes the item into a 16 KiB buffer. An item
//       that fits one message (244 bytes for 0x9C, 239 for 0x9D so the
//       sender's own 0xFC check stays quiet) is copied back and sent exactly
//       as before.
//     - A larger item leaves a 20-byte marker in the sender's buffer, and the
//       full item waits under a token.
//     - When the sender queues its message (0x4817F0), the full item is queued
//       first as 0x9D messages with the private action 0xC7, at most 255 bytes
//       each, directly followed by the item message itself.
//   Client:
//     - The SCMD 0x9D dispatcher (0x12E490) takes the 0xC7 messages and
//       rebuilds the item. The stock client logs and ignores unknown actions,
//       so no other code ever sees them.
//     - Every item handler reads items through D2RCore!ReadItemHeader and
//       D2RCore!DecodeItem (all 33 decode sites in the handlers 0x1C2B10 to
//       0x1C9410). Given a marker, they read the rebuilt item instead.
//   The pieces travel in the same ordered stream as the item message, in
//   local games and over TCP/IP. Nothing is clamped or dropped: the real item
//   reaches the client. The host and every TCP/IP client need this plugin.
//
// ---------------------------------------------------------------------------
// Messages (all numbers little-endian)
// ---------------------------------------------------------------------------
//   Piece: SCMD 0x9D, action 0xC7. 24-byte header, then up to 231 data bytes.
//     +0 9D  +1 C7  +2 length  +3 version 1  +4 "LITF"
//     +8 token  +12 item bytes  +16 item CRC-32  +20 offset of this piece
//   Marker: replaces the item data of the 0x9C/0x9D message, 20 bytes.
//     +0 4C 49 54 53 C7 9D 5A A5  +8 token  +12 item bytes  +16 item CRC-32
//   The client checks the CRC-32 of the rebuilt item before using it.
//
// ---------------------------------------------------------------------------
// Sites (D2R 3.3.93847 under D2RLoader 1.3.1, D2RCore.dll sha256 2a868d01...)
// ---------------------------------------------------------------------------
//   Game image, loader inline hooks:
//     0x4817F0  queue a server message to one client (client, bytes, size_t)
//               40 55 56 57 48 83 EC 40         push rbp/rsi/rdi; sub rsp,40h
//     0x12E490  client SCMD 0x9D dispatcher (message)
//               40 53 48 81 EC 60 01 00 00      push rbx; sub rsp,160h
//   Game image, checked only (fixes the two return addresses):
//     0x479D97  9C sender: mov r8d,0F4h ... call j_SerializeItem; lea esi,[rax+8]
//               the call returns to 0x479DBD
//     0x479F88  9D sender: mov r8d,0F4h ... call j_SerializeItem; lea esi,[rax+0Dh]
//               the call returns to 0x479FA2
//   D2RCore.dll exports, this plugin's own 5-byte detours (D2RLoader 1.3.1's
//   hook installer only accepts sites inside D2R.exe). Each entry is pushes
//   only and nothing in the function branches back into those five bytes:
//     SerializeItem   55 41 56 56 57   (item, buffer, capacity, a4, a5, gamble, sink) -> bytes
//     DecodeItem      55 41 57 41 56   (item, data, size, a4, consumed*, version, error*) -> result
//     ReadItemHeader  55 41 57 41 56   (a1, data, size, a4, header*, version) -> result
//   The game reaches the three exports through its j_ thunks, so every caller
//   passes the detours. D2RCore itself serializes items only inside
//   SerializeItem, so the two senders are the only network item writers.

struct Piece {
    ItemRef             item;
    std::uint32_t       offset;
    const std::uint8_t* data;
    std::size_t         dataBytes;
};

// D2RCore!SerializeItem. The detour is entered by jumps only (game call,
// j_SerializeItem thunk, export entry, relay), so the return address is the
// sender's own call site.

struct CoreHook {
    const char*                               exportName;
    void*                                     target;
    void**                                    original;
    std::array<std::uint8_t, CoreEntryBytes>  expected;  // D2RCore.dll 1.3.1
    std::uint8_t*                             entry;
    std::array<std::uint8_t, CoreEntryBytes>  written;
    bool                                      installed;
};

// =============================================================================
//  Larzuk Restrictions  -  celestialrayone.larzuk-restrictions
//
//  Larzuk refuses to socket items of the configured itemtypes.txt types. The
//  default list is "char", which refuses every charm. A refused item is
//  handled exactly like any other item Larzuk cannot socket: his socket panel
//  does not take it, the server refuses the request, and the quest reward
//  stays unused.
//
//  Built for D2R 3.3 under D2RLoader 1.3.1. Every address below was read out
//  of the dumped D2RLoader 1.3.1 image (md5 8af7a47ce9077de0378c69af2930854d)
//  and disassembled before being relied on. Byte witnesses guard every game
//  address, so a different build refuses cleanly and the game runs stock.
//
// -----------------------------------------------------------------------------
//  LARZUK'S CHECK
// -----------------------------------------------------------------------------
//  0x36B410, int32 (item), D2MOO ITEMS_IsSocketable. 1 means Larzuk may add
//  sockets to the item. It answers 0 for gold, no-sell items, quest items
//  other than "leg", broken items, items that hold something, items already
//  socketed, items whose ITEMS_GetMaxSockets (0x36EAD0) is 0 and items whose
//  item_numsockets (stat 194) is not 0.
//
//  Its only callers in the image:
//    0x4FCD23  D2GAME_NPC_HandleItemServiceTransaction 0x4FC230, service 2
//              (Larzuk). A 0 logs "Unable to upgrade the item" and returns
//              before ITEMS_AddSockets (call at 0x4FD574) and before
//              QUESTS_ConsumeLarzukSocketReward (0x548B60), so nothing is
//              spent.
//    0x1E389B  the client service panel predicate 0x1E37F0
//    0x1E598C  the client service panel slot toggle 0x1E58F0
//              Both call it only while the open NPC is class 511 (Larzuk).
//              A 0 makes the panel refuse the item with the stock refusal.
//  The fourth reference, 0x143C354C8, is the function's .pdata entry.
//
//  The hook takes the prologue up to the first branch:
//      36B410  40 57            push rdi
//      36B412  48 83 EC 20      sub  rsp, 20h
//      36B416  48 8B F9         mov  rdi, rcx       ; item
//      36B419  48 85 C9         test rcx, rcx
//      36B41C  75 13            jnz  36B431         ; not taken by the hook
//  No branch in the function (36B410..36B694) lands inside those 12 bytes and
//  none of them is RIP-relative, so they relocate as they are. The jnz reads
//  the flags of the relocated test, which the jump back does not change.
//
// -----------------------------------------------------------------------------
//  THE RULE
// -----------------------------------------------------------------------------
//  The stock check runs first, so everything it refuses stays refused. Only a
//  yes is overridden: if the item is of one of the configured types, the
//  answer becomes 0.
//
//  The type test is the game's ITEMS_CheckItemTypeId 0x373890 (item, type
//  row), which reads the compiled equivalence table for the item's type and
//  type2. A type therefore also matches every type whose Equiv1/Equiv2 chain
//  reaches it: "char" covers scha, mcha, lcha and, in ESR, qcha, ocha, xcha.
//
//  Codes are matched against itemtypes.txt on every call, in the item's own
//  data context (0x34A0E0, byte [unit+1BDh]) and that context's tables
//  (0x300A90): rows at +1348h, row count at +1350h, 0E8h bytes per row, the
//  code in the first four bytes. The itemtypes.txt loader 0x318690 proves it
//  when it hands every row's code to the code linker:
//      318E40  lea  rdi, [rsi+1348h]          ; rsi = tables
//      318EA8  mov  rbx, [rdi]                ; first row
//      318EAB  imul rdi, [rdi+8], 0E8h        ; row count * row size
//      318EC0  mov  edx, [rbx]                ; the row's code
//      318ECA  add  rbx, 0E8h
//      318ED6  mov  rbx, [rsi+1350h]          ; row count
//  and ITEMS_CheckItemTypeId bounds its type row by the same count:
//      3738E9  mov  rbx, [rax+1350h]
//
//  Console command "larzukrestrictions" shows the settings, state and counters.
//  Settings: d2rloader/config/celestialrayone.larzuk-restrictions.toml
// =============================================================================

// =============================================================================
//  Left Click Auras  -  celestialrayone.left-click-auras
//
//  D2R 3.3 under D2RLoader 1.3.1. An aura on the LEFT mouse button runs like an
//  aura on the right button, and both run at the same time. Port of ESR's 2.4
//  left click aura patch set, plus controller support:
//
//    1. LEFT SLOT AURAS. Putting an aura on the left button starts it; taking
//       it off, by any route, stops it and removes its state and bonuses.
//    2. SINGLE EMANATION. The same aura on both buttons emanates once.
//    3. MOVE ONLY CLICKS. A left click on a monster with an aura on the left
//       button moves toward it instead of doing nothing.
//    4. LIVE LEVEL. Every tick the left aura takes its level from the skill on
//       the left button, as the right button's aura does.
//    5. CONTROLLER AURAS. Auras can be switched on with a controller, and up to
//       two run at once, one per side.
//    6. AURA LEVEL REFRESH. An aura that comes back at a higher level keeps its
//       state instead of blinking off, on either button and for every unit.
//    7. ITEM REFRESH KEEPS AURAS. An aura granted by an item (oskill), on either
//       button, keeps running while the game re-checks the equipment, instead
//       of being switched off and started again.
//
//  Every address below was read out of the dumped D2RLoader 1.3.1 image
//  (md5 8af7a47ce9077de0378c69af2930854d) and disassembled before being relied
//  on. Byte witnesses guard every function the plugin changes or relies on, so
//  a different build refuses cleanly.
//
// -----------------------------------------------------------------------------
//  HOW THE GAME RUNS AN AURA (server)
// -----------------------------------------------------------------------------
//  0x438A70  AssignSkill(unit, side, skillId, ownerGuid); side != 0 is the left
//            button, side 0 the right one. rbp = unit, r15d = side, r14d = skill.
//      left   0x438AEF  SetLeftActiveSkill, then 0x438B96 test r15d,r15d /
//                       jnz 0x438C85 skips every aura step.
//      right  0x438AF6  old right node into r12, SetRightActiveSkill
//             0x438B9F  old right aura, any aura on the left ignored:
//                       0x438C02 GetStateStatList -> unlink, free
//                       0x438C33 ToggleState(unit, state, 0)
//                       0x438C52 delete (8, -1)
//             0x438C80  new right aura: AuraStart(game, unit, skillId)
//
//  0x43B680  AuraStart: skills.txt record, aura flag byte[rec+24h] & [1D996E4h],
//            aurastate word[rec+A0h] inside the state table, real level, new
//            cast id. State stat list (reused or allocated) gets stat 350 =
//            skill, 351 = level, 202 = cast id, state on. Then
//            0x43B8FD ArmPeriodicSkill(game, unit, skill, level, castId, 1).
//
//  0x43B2B0  ArmPeriodicSkill: event type 8 with custom id -1 when the last
//            argument is 1 (the right button's timer), else the skill id (a
//            timer of its own, level in customParam, cast id in arg7). It
//            deletes that (8, id) event before setting it, so arming again
//            never stacks timers. Ticks land on frames aligned to the period
//            (perdelay, at least 5), the same frames 0x434CC0 gives srvdofunc
//            65 for the duration of the state list it applies.
//
//  0x437460  the type 8 event(game, unit, customId, customParam, arg7)
//      id -1  the right button's timer. Reads the RIGHT button (0x437499),
//             needs the aura flag and a living unit (0x437503), takes the
//             level every tick (0x4374CE, ReadWideSkillLevel(unit, node, 1,
//             0)), sets the timer's cast id on the unit (0x437538 / 0x437545),
//             unit flag 20000000h around the perform (0x437558 / 0x43758E),
//             performs at 0x43757E (0x43ACB0: level, 1, 0, 0), re-arms with
//             the last argument 1 and puts the unit's cast id back. A right
//             skill that is no longer an aura, or a dead unit, deletes (8, -1).
//      id > 0 the timer of a cast skill. It checks the aura state's stat list,
//             not a button: state on (0x43767A), list present (0x437691), unit
//             still has the skill (0x4376C5), stat 350 on the list == skill
//             (0x4376ED); level from stat 351 of that list (0x4376B5). Any
//             failure calls 0x432450, which deletes (8, skill).
//
//  That stat list is SHARED. Everything that applies the same state to the
//  unit writes it: the srvdofunc 65 callback 0x5616F0 stamps 350 / 351 / 202 at
//  0x561D16 / 0x561D38 / 0x561D5A and resets the expiry when the list's owner
//  is another unit (0x5617FB). The applier's rules (D2MOO sub_6FD10EC0):
//      same skill, same level   list reused, expiry set by this application
//      same skill, list higher  this application is refused, nothing refreshed
//      same skill, list lower   list freed and rebuilt (see AURA LEVEL REFRESH)
//      other skill              list freed and rebuilt for the other skill
//  A list expires one frame after the tick of whoever applied it last.
//
//  WHY LEFT AURAS TURNED THEMSELVES OFF (1.1.0 and earlier): the left aura ran
//  on the id > 0 timer. A hireling, bound demon, party member or item with the
//  same aura at a higher level took the list over and refused the player's own
//  application; when that unit left range, died or lost the aura, the list
//  expired and the next left tick found the state off. Another skill row with
//  the same aurastate (an item or monster version of the aura) rebuilt the
//  list with its own stat 350. An item aura with the same state being removed
//  or refreshed cleared it. Every one of those failed the id > 0 checks, and
//  the aura stayed off until it was selected again. The right button's timer
//  never reads that list, so the same events only made a right aura blink.
//
// -----------------------------------------------------------------------------
//  THE FIX (server)
// -----------------------------------------------------------------------------
//  0x438AEF  call relay on the left branch's SetLeftActiveSkill (rcx unit,
//            edx skill, r8d owner guid; eax unused afterwards). The stock code
//            only gets there after 0x33DCD0 found the skill. Left skill before
//            and after the stock select:
//              - the old left aura is not the new left skill: remove its state
//                stat list and state (kept when the right button's aura uses
//                the same state and its timer runs), delete (8, old skill).
//              - the new left skill is an aura: nothing when it is the same
//                aura with this plugin's timer live and its state on;
//                otherwise AuraStart runs with its final arm switched to the
//                skill's own timer (next item).
//  0x43B8FD  call relay. Only for the AuraStart the relay above runs: the last
//            argument becomes 0, and the (unit, skill, cast id) of the timer is
//            remembered. Every other AuraStart runs untouched.
//  0x438C02,
//  0x438C33  call relays inside the right button's aura removal. When the left
//            button holds a running aura with that same state, the state stat
//            list is reported missing and the state stays on. The right timer
//            is still deleted.
//  0x437460  inline hook. A remembered left timer (unit, skill, exact cast id)
//            runs the right button's timer logic against the LEFT button and
//            never reaches the id > 0 checks: left button still holds the
//            skill, aura flag, living unit, level (live or the armed one),
//            cast id and unit flag exactly as the id -1 branch sets them,
//            perform through 0x43ACB0 (skipped for single_emanation), re-arm
//            through 0x43B2B0 with the last argument 0. Otherwise it stops
//            the aura: state stat list and state removed (kept when the right
//            button's running aura uses the same state), (8, skill) deleted.
//            Every other timer runs stock, so timers the game creates itself
//            (monsters, cast skills) are never touched.
//
// -----------------------------------------------------------------------------
//  MOVE ONLY CLICKS (client)
// -----------------------------------------------------------------------------
//  0x102490  world click handler(command). rdi = command; flags dword at +0
//            (1 left button, 2 right, 4 press, 20h shift), player +8, target
//            +10h, skill node +28h (r14 = command+28h).
//  0x102753  call 0x33F770(player, node), which returns dword [node+10h]:
//            nonzero sends the click into the skill branch. There 0x100970
//            asks the usability gate 0x100760 -> 0x21B170 -> classifier
//            0x33F360, which returns 6 for an aura (byte[rec+24h] &
//            [1D996E4h]); the gate lets only 0 and 5 through, so nothing
//            happens. Zero leaves the skill branch: a monster press is sent as
//            a move toward it (0x0FABE0 with the command's unit opcode), NPCs
//            and every other unit type go to 0x101910 (talk, interact, pick
//            up, use, with a move toward the target when out of range).
//            Call relay: lea r8,[r14-28h] hands the command over; a left button
//            click whose node is the player's left skill holding an aura
//            returns 0. Everything else calls 0x33F770.
//
// -----------------------------------------------------------------------------
//  CONTROLLER AURAS (client)
// -----------------------------------------------------------------------------
//  Controller bindings: 16 buttons per bank, 28-byte entries at 0x2A48A90 +
//  28 * (button + bank 0x1195C0()): +0 skill, +4 owner guid, +8 side (1 left,
//  0 right). 0x117DE0 returns the side, 0x117D20 the skill, 0x117CC0 the guid.
//  When a skill is bound, 0x238910 picks the side from skills.txt leftskill
//  (byte[rec+27h] & [1D996E8h]); there is no other choice on a controller.
//
//  0x12BB40  the client's handler for the server's skill confirmation packet
//            (+2 unit id, +6 side, +7 skill, +9 guid; rbx = packet). For the
//            local player in controller mode, a toggle skill (0x14A970, auras
//            through controllerskillsettings.json) must be bound on side 0:
//            0x12BBD7 mov r8d,r14d / xor edx,edx / mov rcx,rsi / call 0x14A930
//            (0x117BD0 binding lookup). When it is not, the client sends skill
//            0 (Attack) for that side (0x12BC03, message 3Ch) and selects it
//            locally. A leftskill aura is bound on side 1, so it is switched
//            back to Attack the moment the server confirms it: auras could not
//            be activated at all.
//            FIX, call relay at 0x12BBDF: the stub loads edx = (byte [rbx+6]
//            != 0), the side the server confirmed, then calls 0x14A930.
//
//  0x144AC0  the controller press processor; for a press it calls 0x14A5A0
//            (manager, player index, button) at 0x144B00, which reads the
//            button's side at 0x14A664 (0x117DE0), takes that side's current
//            skill (0x34A540 left / 0x34B400 right) and switches it to the
//            button's skill. Every later step of that press (cast command
//            0x14B1A0, confirmation check above) reads the same binding side.
//            FIX, call relay at 0x144B00: for a button holding an aura, the
//            binding's side byte is set first: the side already running that
//            aura; else the right side when no aura runs there; else the left
//            side when no aura runs there and the row has leftskill; else the
//            side whose aura was switched on earlier. Then 0x14A5A0 runs.
//
// -----------------------------------------------------------------------------
//  AURA LEVEL REFRESH (server, both buttons, every unit)
// -----------------------------------------------------------------------------
//  0x5616F0  the basic aura callback (srvdofunc 65), called for the caster
//            itself and for every unit in range. It fills a request on its
//            stack at [rbp-19h] (0x56171C..0x561774) and calls the state
//            applier at 0x561778, return address 0x56177D:
//              +00h caster    +08h target    +10h skill     +14h level
//              +18h duration  +1Ch stat (-1) +20h value (0) +24h state
//              +28h remove callback: the aura's own, else 0x566170 when the
//                   target is the caster, else none (the applier then
//                   uses 0x436240)
//  0x433D20  the state applier. D2RLoader turned its entry into a thunk,
//            jmp [rip+39F671Ah], so the code that runs is D2RLoader's
//            ApplyWideTimedStatEffect, reached through the pointer at
//            0x3E2A440. The game's own body is still in the image from
//            0x433D26:
//              list = curse state (0x335A40) ? the unit's curse list
//                     (0x2F5810, flag 20h) : the unit's list for the state
//                     (0x2F5940)
//              same state, same skill (list +28h), same level (list +2Ch):
//                     expiry refreshed (0x2F7AB0), the list is returned
//              same skill, lower level: refused, returns 0 (0x434076)
//              anything else, a HIGHER level included: unlink (0x2F7920) and
//                     free (0x2F4180) the old list, which removes every stat
//                     on it and runs its remove callback (state off); then
//                     state on (0x3354C0) and a new list (0x2F7300) with the
//                     caster as owner (list +08h type, +0Ch id) and the
//                     request's remove callback (list +80h)
//  So every time the same aura comes back one level higher, its bonuses are
//  removed and added again inside one frame, and the client sees its state
//  blink. When the torn down list belonged to another unit's aura, its remove
//  callback 0x436240 recounts the player's pet limits (0x5005A0, called at
//  0x4362CC) while the bonuses are missing: an aura that grants +skills
//  lowers every summon skill's petmax for that instant, and the game kills
//  the summons above it. Divinity raises its own level, so it climbs through
//  one rebuild per level, and a Divinity from another unit takes the list
//  over through the same rebuild.
//
//  FIX: the plugin points the thunk's pointer 0x3E2A440 at its own function.
//  No game code byte changes (celestialrayone.aura-zero-branch byte-checks
//  0x5616F0..0x5617A6, the applier call included). Calls from anywhere but
//  the aura callback (return address 0x56177D) go straight on to D2RLoader's
//  applier. For the aura callback:
//    1. It finds the list the applier will look at, the way the applier finds
//       it. When that list holds the same skill at a LOWER level than the
//       request, it raises the list's level to the request's (0x2F7A00).
//    2. The applier then takes its same-level path: it keeps the list and
//       refreshes its expiry. If the applier refuses for one of its own
//       reasons (its monster and curse checks), it returns 0 before it
//       touches the list, and the plugin puts the old level back.
//    3. When the list came back, the plugin finishes what the rebuild would
//       have changed, without removing the aura's bonuses:
//         same caster   a list without a remove callback (one AuraStart
//                       0x43B680 made) gets the one the rebuild would have
//                       given it (level_up_in_place)
//         other caster  owner (0x2F6CA0), other-caster record (0x2F6CB0) and
//                       remove callback move to the new caster; when the
//                       target owned the list, the passive stats its own
//                       application wrote (skills.txt passivestat1-14,
//                       record +0BAh, see 0x563FFC) are removed, as the
//                       rebuild removed them (takeover_in_place)
//         both          the state is turned on if it was off
//  Lower levels are still refused, and different skills that share a state
//  still replace each other, as in the unmodded game.
//
// -----------------------------------------------------------------------------
//  ITEM REFRESH KEEPS AURAS (server, both buttons)
// -----------------------------------------------------------------------------
//  0x470CA0  the equipment re-check (ITEMS_UpdateInventoryItems). It saves the
//            mouse selection (0x474C00), takes EVERY equipped item off with
//            unit flag 80000000h set around each detach (0x470E77..0x470EA8),
//            puts back the items whose requirements are met, the flag set
//            around each attach as well (0x470F79..0x470FAA), puts the saved
//            selection back through AssignSkill (0x474AA0, called at
//            0x47109E), deletes skills left without level, counts the pet
//            limits (0x5005A0, called at 0x4711C3) and settles the item auras
//            it kept back (0x4711C8..0x47121E, below). It runs after item moves
//            (0x471835), level ups (0x52DCA1), skill resets (0x436217) and in
//            every frame in which the player carries unit flag 200000h: the
//            per-frame player sync tests it at 0x486A6D and calls 0x470C90 ->
//            0x470CA0. The server stat callback sets that flag whenever
//            passive_mastery_item_req_percent (203) or
//            passive_mastery_item_level_req_percent (209) changes outside an
//            item operation (0x470998..0x4709AD).
//  0x46FE1B  the server stat callback, oskill case (item_nonclassskill 97,
//            item_singleskill 107, 0x4702AE..0x4702EE): when the stat drops to
//            0 and the skill has no base level, every mouse button holding the
//            skill gets Attack through AssignSkill (left 0x4702C9, right
//            0x4702E9). D2RLoader's core runs its own version of this callback
//            (see celestialrayone.aura-reactivation); the game's body above is
//            what it reproduces. Inside the re-check that happens to every
//            oskill for an instant. An oskill AURA was then switched off (the
//            right button's removal in AssignSkill, this plugin's left select)
//            and started again by the selection restore: the state blinked, its
//            bonuses were gone until its next tick and the pet limits were
//            counted without them.
//            The same callback already treats item auras (item_aura 151) as a
//            transaction while flag 80000000h is set: a removal goes to a
//            pending list (game +1A8F0h, count +1A8F8h), a grant that comes
//            back reuses its cast id, and what was not granted back is switched
//            off when the re-check ends (0x4711C8..0x47121E, 0x581AE0). Auras
//            on the mouse buttons had no such rule.
//  The loop seen with Divinity (oskill, raises item_allskills) and Levitation
//  Mastery (oskill passive, its passive_mastery_item_req_percent follows its
//  level): every restart changed item_allskills on the aura's next tick, that
//  changed Levitation Mastery's level and the modifier, the flag was set, the
//  re-check ran and restarted the aura again. On every tick the overlay
//  replayed and the bonuses were missing.
//
//  FIX: the item aura rule, for auras on the mouse buttons.
//    - While flag 80000000h is set (0x34FB00), an aura that runs on a button
//      that gets another skill keeps running and is remembered. Left: the left
//      select relay does not stop it. Right: the call relays at 0x438C02,
//      0x438C33 and 0x438C52 skip its stat list, state and timer removal.
//    - When its button gets it back, it carries on. Left: it counts as running.
//      Right: the AuraStart call at 0x438C80 is skipped. The same holds when
//      the button was changed without AssignSkill and gets the aura back
//      before its timer ticks: the timer is still live, the aura never
//      stopped.
//    - An aura its button did not get back is stopped when the re-check ends
//      (call relay at 0x4711C3, before the pet limits are counted), at the
//      next selection change outside an item operation, or by its own timer.
//    0x438B09  call relay on AssignSkill's SetRightActiveSkill (rcx unit, edx
//              skill, r8d owner guid; eax unused afterwards): the right
//              button's skill before and after.
//    0x438C52  call relay on the right timer delete (rcx game, rdx unit, r8d 8,
//              r9d -1).
//    0x438C80  call relay on the new right aura's AuraStart (rcx game, rdx
//              unit, r8d skill; its eax is AssignSkill's, unused by callers).
//    0x4711C3  call relay on the pet limit count (rcx game, rdx unit).
//
//  Console command "leftclickauras" shows what is installed and counters.
//  Settings: d2rloader/config/celestialrayone.left-click-auras.toml
// =============================================================================

// 0x437460..0x4375AA, the type 8 event: entry, the right button's timer. Its
// call bytes prove 0x34B400, 0x33D1E0, 0x097790, 0x34C2C0, 0x34B6C0, the
// SetUnitCastId thunk 0x3E2B652 (1.3.1; 0x3E2B57E in 1.3.0), 0x34E140 and
// 0x43ACB0, which the left timer calls the same way.

// ---------------------------------------------------------------------------
//  Relay page. One page the plugin allocates within rel32 reach of the image;
//  nothing inside D2R's own code is used as a cave.
//
//      +0x000  UNWIND_INFO, no frame (every stub leaves rsp untouched)
//      +0x010  RUNTIME_FUNCTION table, 11 entries
//      +0x100  mov rax,<bridge> / jmp rax      left select
//      +0x120  mov rax,<bridge> / jmp rax      right aura stat list
//      +0x140  mov rax,<bridge> / jmp rax      right aura state off
//      +0x160  mov rax,<bridge> / jmp rax      AuraStart arm
//      +0x180  lea r8,[r14-28h] / mov rax,<bridge> / jmp rax   click gate
//      +0x1A0  cmp byte [rbx+6],0 / setne dl / movzx edx,dl /
//              mov rax,<bridge> / jmp rax      controller confirmation side
//      +0x1C0  mov rax,<bridge> / jmp rax      controller press
//      +0x1E0  mov rax,<bridge> / jmp rax      right select
//      +0x200  mov rax,<bridge> / jmp rax      right timer delete
//      +0x220  mov rax,<bridge> / jmp rax      right AuraStart
//      +0x240  mov rax,<bridge> / jmp rax      equipment re-check pet limits
//
//  A stub is reached by the retargeted call, so the return address is on the
//  stack and the stock arguments are in place: the bridge is entered as if
//  the game had called it. rax and r8 are volatile and not arguments of the
//  replaced callees (0x33F770 takes two). At 0x12BBDF rbx is the packet and
//  edx is about to be the constant 0, so the stub only replaces edx.
// ---------------------------------------------------------------------------

struct CallSitePatch {
    std::uint64_t               rva;
    const std::uint8_t*         stock;
    std::size_t                 stub;
    std::array<std::uint8_t, 5> written;
    bool                        applied;
};

